window.PACK={"book":{"id":"alfiyya","title":"ألفية ابن مالك","type":"lughabook","ilm":"nahw","author":"ابن مالك (ت ٦٧٢هـ)","source":"المكتبة الشاملة / هنداوي عبر مشروع OpenITI","edition":"دار التعاون","optional":true,"packVersion":"22e13d676808"},"items":[{"id":"alfiyya:1","bookId":"alfiyya","type":"section","seq":1,"chapter":"مقدمة المؤلف","title":"مقدمة المؤلف","page":"","text":"...\n(بسم الله الرحمن الرحيم)\nقال محمد هو ابن مالك ... أحمد ربي الله خير مالك\nمصليا على النبي المصطفى ... وآله المستكملين الشرفا\nوأستعين لله في ألفيه ... مقاصد النحو بها محويه\nتقرب الأقصى بلفظ موجز ... وتبسط البذل بوعد منجز\nوتقتضي رضا بغير سخط ... فائقة ألفية ابن معطي\nوهو بسبق حائز تفضيلا ... مستوجب ثنائي الجميلا\nوالله يقضي بهبات وافرة ... لي وله في درجات الآخرة"},{"id":"alfiyya:2","bookId":"alfiyya","type":"section","seq":2,"chapter":"مقدمة المؤلف","title":"الكلام وما يتألف منه","page":"ج1 ص9","text":"كلامنا لفظ مفيد كاستقم ... واسم وفعل ثم حرف الكلم\nواحده كلمة والقول عم ... وكلمة بها كلام قد يؤم\nبالجر والتنوين والندا وآل ... ومسند للاسم تمييز حصل\nبتا فعلت وأتت ويا افعلي ...\nونون أقبلن فعل ينجلي\nسواهما الحرف كهل وفي ولم ... فعل مضارع يلي لم كيشم\nوماضي الأفعال بالتامز وسم ... بالنون فعل الأمر إن أمر فهم\nوالأمر إن لم يك للنون محل ... فيه فهو اسم نحوصه وحيهل"},{"id":"alfiyya:3","bookId":"alfiyya","type":"section","seq":3,"chapter":"مقدمة المؤلف","title":"المعرب والمبني","page":"ج1 ص10","text":"والاسم منه معرب ومبني ... لشبه من الحروف مدني\nكالشبه الوضعي في اسمي جئتنا ... والمعنوي في متى وفي هنا\nوكنيابة عن الفعل بلا ... تأثر وكافتقار أصلا\nومعرب الأسماء ما قد سلما ... من شبه الحرف كأرض وسما\nوفعل أمر ومضي بنيا ... وأعربوا مضارعا إن عريا\nمن نون توكيد مباشر ومن ... نون إناث كيرعن من فتن\nوكل حرف مستحق للبنا ... والأصل في المبني أن يسكنا\nومنه ذو فتح وذو كسر وضم ... كأين أمس حيث والساكن كم\nوالرفع والنصب اجعلن اعرابا ... لاسم وفعل نحو لن أهابا\nوالاسم قد خصص بالجر كما ... قد خصص الفعل بأن ينجزما\nفارفع بضم وانصبن فتحا وجر ... كسرا كذكر الله عبده يسر\nواجزم بتسكين وغير ما ذكر ... ينوب نحو جاأخو بني نمر\nوارفع بواو وانصبن بالألف ... واجرر بياء ما من الأسماء أصف\nمن ذاك ذو إن صحبة أبانا ... والفم حيث الميم منه بانا\nأب أخ حم كذاك وهن ... والنقص في هذا الأخير أحسن\nوفي أب وتالييه يندر ... وقصرها من نقصهن أشهر\nوشرط ذا الاعراب إن يضفن لا ... للياكجا أخو أبيك ذا اعتلا\nبالألف ارفع المثنى وكلا ... إذا بمضمر مضافا وصلا\nكلتا كذاك اثنان واثنتان ... كابنين وابنتين يجريان\nوتخلف اليا في جميعها الألف ... جرا ونصبا بعد فتح قد ألف\nوارفع بواو وبيا واجرر وانصب ... سالم جمع عامر ومذنب\nوشبه ذين وبه عشرونا ... وبابه ألحق والأهلونا\nأولو وعالمون عليونا ... وأرضون شذ والسنونا\nوبابه ومثل حين قد يرد ... ذا الباب وهو عند قوم يطرد\nونون مجموع وما به ألتحق ... فافتح وقل من بكسره نطق\nونون ما ثني والملحق به ... بعكس ذاك استعملوه فانتبه\nومابتا وألف قد جمعا ... يكسر في الجر وفي النصب معا\nكذا أولات والذي اسما قد جعل ... كأذرعات فيه ذا أيضا قبل\nوجر بالفتحة ما لا ينصرف ... ما لم يضف أو يك بعد أل ردف\nواجعل لنحو يفعلان النونا ... رفعا وتدعين وتسألونا\nوحذفها للجزم والنصب سمه ... كلم تكوني لترومي مظلمه\nوسم معتلا من الأسماء ما ... كالمصطفى والمرتقى مكارما\nفالأول الإعراب فيه قدرا ... جميعه وهو الذي قد قصرا\nوالثاني منقوص ونصبه ظهر ... ورفعه ينوي كذا أيضا يجر\nوأي فعل آخر منه ألف ... أو واو او ياء فمعتلا عرف\nفالألف انوفيه غير الجزم ... وأبد نصب ما كيدعو يرمي\nوالرفع فيهما انوواحذف جازما ... ثلاثهن تقض حكما لازما"},{"id":"alfiyya:4","bookId":"alfiyya","type":"section","seq":4,"chapter":"مقدمة المؤلف","title":"النكرة والمعرفه","page":"ج1 ص12","text":"نكرة قابل أل مؤثرا ... أو واقع موقع ما قد ذكرا\nوغيره معرفة كهم وذي ... وهند وابني والغلام والذي\nفما لذي غيبة أو حضور ... كأنت وهو سم بالضمير\nوذو اتصال منه ما لا يبتدا ... ولا يلي إلا اختيارا أبدا\nكالياء والكاف من ابني أكرمك ... والياء والها من سلييه ما ملك\nوكل مضمر له البنا يجب ... ولفظ ما جر كلفظ ما نصب\nللرفع والنصب وجرنا صلح ... كاعرف بنا فإننا نلنا المنح\nوألف والواو والنون لما ... غاب وغيره كقاما واعلما\nومن ضمير الرفع ما يستتر ... كافعل أوافق نغتبط إذ تشكر\nوذو إرتفاع وانفصال أنا هو ... وأنت الفروع لا تشتبه\nوذو انتصاب في انفصال جعلا ... إياي والتفريع ليس مشكلا\nوفي اختيار لا يجيء المنفصل ... إذ تأتى أن يجئ المتصل\nوصل أو افصل هاء سلنيه وما ... أشبهه في كنته الخلف أنتمي\nكذاك خلتنيه واتصالا ... أختار غيري اختار الانفصالا\nوقدم الأخص في اتصال ... وقدمن ما شئت في اتفصال\nوفي اتحاد الرتبة الزم فصلا ... وقد يبيح الغيب فيه وصلا\nوقبل يا النفس مع الفعل التزم ... نون وقاية وليسي قد نظم\nوليتني فشا وليتي ندرا ... ومع لعل اعكس وكن مخيرا\nفي الباقيات واضطرارا خففا ... مني وعني بعض من قد سلفا\nوفي لدني لدني قل وفي ... قدني وقطني الحذف أيضا قد يفي"},{"id":"alfiyya:5","bookId":"alfiyya","type":"section","seq":5,"chapter":"مقدمة المؤلف","title":"العلم","page":"ج1 ص13","text":"اسم يعين المسمى مطلقا ... علمه كجعفر وخرنقا\nوقرن وعدن ولاحق ... وشدقم وهيلة وواشق\nواسما أتى وكنية ولقبا ... وأخرن ذا إن سواه صحبا\nوإن يكونا مفردين فأضف ... حتما وإلا أتبع اي ردف\nومنه منقول كفضل وأسد ... وذو ارتجال كسعاد وأدد\nوجملة وما بمزج ركبا ... ذا إن بغير ويه تم أعربا\nوشاع في الأعلام ذو الإضافه ... كعبد شمس وأبي قحافة\nووضعوا لبعض الأجناس علم ... كعلم الأشخاص لفظا وهو عم\nمن ذاك أم عريط للعقرب ... وهكذا ثعالة للثعلب\nومثله برة للمبرة ... كذا فجار علم للفجرة"},{"id":"alfiyya:6","bookId":"alfiyya","type":"section","seq":6,"chapter":"مقدمة المؤلف","title":"اسم الإشاره","page":"ج1 ص14","text":"بذا لمفرد مذكر أشر ... بذي وذه تي تا على الأنثى اقتصر\nوذان تان للمثنى المرتفع ... وفي سواه ذين تين اذكر تطع\nوبأولى أشر لجمع مطلقا ... والمد أولى ولدى البعد انطقا\nبالكاف حرفا دون لام أو معه ... واللام إن قدمت هاممتنعة\nوبهنا أو ههنا أشر إلى ... داني المكان وبه الكاف صلا\nفي البعد أو بثم فه أو هنا ... أو بهنالك انطقن أو هنا"},{"id":"alfiyya:7","bookId":"alfiyya","type":"section","seq":7,"chapter":"مقدمة المؤلف","title":"الموصول","page":"ج1 ص15","text":"موصول الأسماء الذي الأنثى التي ... واليا إذا ما ثنيا لا تثبت\nبل ما تليه أوله العلامه ... والنون إن تشدد فلا ملامه\nوالنون من ذين وتين شددا ... أيضا وتعويض بذاك قصدا\nجمع الذى الألى الذين مطلقا ... وبعضهم بالواو رفعا نطقا\nباللات واللاء التي قد جمعا ... واللاء كالذين نزرا وقعا\nومن وما وأل تساوي ما ذكره ... وهكذا ذو عند طيئ شهر\nوكالتي أيضا لديهم ذات ... وموضع اللاتي أتى ذوات\nومثل ماذا بعدما استفهام ... أومن إذا لم تلغ في الكلام\nوكلها يلزم بعده صله ... على ضمير لائق مشتمله\nوجملة أو شبهها الذي وصل ... به كمن عندي الذي ابنه كفل\nوصفة صريحة صلة أل ... وكونها بمعرب الأفعال قل\nأي كما وأعربت ما لم تضف ... وصدر وصلها ضمير انحذف\nوبعضهم أعرب مطلقا وفي ... ذا الحذف أيا غير أي يقتفي\nإن يستطل وصل وإن لم يستطل ... فالحذف نزر وأبوا أن يختزل\nإن صلح الباقي لوصل مكمل ... والحذف عندهم كثير منجلي\nفي عائد متصل إن انتصب ... بفعل أو وصف كمن نرجو يهب\nكذاك حذف ما بوصف خفضا ... كأنت قاض بعد أمر من قضى\nكذا الذي جربما الموصول جر ... كمر بالذي مررت فهو بر"},{"id":"alfiyya:8","bookId":"alfiyya","type":"section","seq":8,"chapter":"مقدمة المؤلف","title":"المعرف بأداة التعريف","page":"ج1 ص16","text":"أل حرف تعريف أو اللام فقط ... فنمط عرفت قل فيه النمط\nوقد تزاد لازما كاللات ... والآن والذين ثم اللات\nولاضطرار كبنات الأوبر ... كذا وطبت النفس يا قيس السرى\nوبعض الأعلام عليه دخلا ... للمح ما قد كان عنه نقلا\nكالفضل والحارث والنعمان ... فذكر ذا وحذفه سيان\nوقد يصير علما بالغلبه ... مضاف أو مصحوب أل كالعقبة\nوحذف أل ذي إن تناد أو تضف ... أوجب وفي غيرهما قد تحذف"},{"id":"alfiyya:9","bookId":"alfiyya","type":"section","seq":9,"chapter":"مقدمة المؤلف","title":"الابتداء","page":"ج1 ص16","text":"مبتدأ زيد وعاذر خبر ... إن قلت زيد عاذر من اعتذر\nوأول مبتدأ والثاني ... فاعل اغنى في أسار ذان\nوقس كاستفهام النفي وقد ... يجوز نحو فائز أولو الرشد\nوالثاني مبتدا وذا الوصف خبر ... إن في سوى الإفراد طبقا استقر\nورفعوا مبتدأ بالابتدا ... كذاك رفع خبر بالمبتدا\nوالخبر الجزء المتم الفائدة ... كالله بر والأيادي شاهده\nومفردا يأتي ويأتي جمله ... حاوية معنى الذي سيقت له\nوإن تكن إياه معنى اكتفى ... بها كنطقي الله حسبي وكفى\nوالمفرد الجامد فارغ وإن ... يشتق فهو ذو ضمير مستكن\nوأبرزنه مطلقا حيث تلا ... ما ليس معناه له محصلا\nوأخبروا بظرف أو بحرف جر ... ناوين معنى كائن أو استقر\nولا يكون اسم زمان خبرا ... عن جثة وإن يفد فأخبرا\nولا يجوز الابتدا بالنكرة ... ما لم تفد كعند زيد نمرة\nوهل فتى فيكم فما حل لنا ... ورجل من الكرام عندنا\nورغبة في الخير خير وعمل ... بر يزين وليقس ما لم يقل\nوالأصل في الأخبار أن تؤخرا ... وجوزوا التقديم إذ لا ضررا\nفامنعه حين يستوي الجزءان ... عرفا ونكرا عادمي بيان\nكذا إذا ما الفعل كان الخبرا ... أو قصد استعماله منحصرا\nأو كان مسندا لذي لام ابتدا ... أو لازم الصدر كمن لي منجدا\nونحو عندي درهم ولي وطر ... ملتزم فيه تقدم الخبر\nكذا إذا عاد عليه مضمر ... مما به عنه مبينا يخبر\nكذا إذا يستوجب التصديرا ... كأين من علمته نصيرا\nوخبر المحصور قدم أبدا ... كما لنا إلا اتباع أحمدا\nوحذف ما يعلم جائز كما ... تقول زيد بعد من عندكما\nوفي جواب كيف زيد قل دنف ... فزيد استغني عنه إذ عرف\nوبعد لولا غالبا حذف الخبر ... حتم وفي نص يمين ذا استقر\nوبعد واو عينت مفهوم مع ... كمثل كل صانع وما صنع\nوقبل حال لا يكون خبرا ... عن الذي خبره قد أضمرا\nكضربي العبد مسيئا وأتم ... تبييني الحق منوطا بالحكم\nوأخبروا باثنين أو بأكثرا ... عن واحد كهم سراة شعرا"},{"id":"alfiyya:10","bookId":"alfiyya","type":"section","seq":10,"chapter":"مقدمة المؤلف","title":"كان وأخواتها","page":"ج1 ص18","text":"ترفع كان المبتدا اسما والخبر ... تنصبه ككان سيدا عمر\nككان ظل بات أضحى أصبحا ... أمسى وصار ليس زال برحا\nفتئ وانفك وهذي الأربعة ... لشبه نفى أو لنفي متبعه\nومثل كان دام مسبوقا بما ... كأعط ما دمت مصيبا درهما\nوغير ماض مثله قد عملا ... إن كان غير الماض منه استعملا\nوفي جميعها توسط الخبر ... أجز وكل سبقه دام حظر\nكذاك سبق خبر ما النافية ... فجيء بها متلوة لا تالية\nومنع سبق خبر ليس اصطفي ... وذو تمام ما برفع يكتفي\nوما سواه ناقص والنقص في ... فتىء ليس زال دائما قفي\nولا يلي العامل معمول الخبر ... إلا إذا ظرفا أتى أو حرف جر\nومضمر الشان اسما انو ان وقع ... موهم ما استبان أنه امتنع\nوقد تزاد كان في حشو كما ... كان أصح علم من تقدما\nويحذفونها ويبقون الخبر ... وبعد إن ولو كثيرا ذا اشتهر\nوبعد أن تعويض ما عنها ارتكب ... كمثل أما أنت برا فاقترب\nومن مضارع لكان منجزم ... تحذف نون وهو حذف ما التزم"},{"id":"alfiyya:11","bookId":"alfiyya","type":"section","seq":11,"chapter":"مقدمة المؤلف","title":"فصل في ما ولا ولات وإن المشبهات بليس","page":"ج1 ص19","text":"...\nإعمال ليس أعملت ما دون إن ... مع بقا النفي وترتيب زكن\nوسبق حرف جر أو ظرف كما ... بي أنت معنيا أجاز العلما\nورفع معطوف بلكن أو ببل ... من بعد منصوب بما الزم حيث حل\nوبعد ما وليس جرالبا الخبر ... وبعد لا ونفي كان قد يجر\nفي النكرات أعملت كليس لا ... وقد تلي لات وإن ذا العملا\nوما للات في سوى حين عمل ... وحذف ذي الرفع فشاو العكس قل"},{"id":"alfiyya:12","bookId":"alfiyya","type":"section","seq":12,"chapter":"مقدمة المؤلف","title":"أفعال المقاربة","page":"ج1 ص20","text":"ككان كاد وعسى لكن ندر ... غير مضارع لهذين خبر\nوكونه بدون أن بعد عسى ... نزر وكاد الأمر فيه عكسا\nوكعسى جرى ولكن جعلا ... خبرها حتما بأن متصلا\nوألزموا اخلولق أن مثل حرى ... وبعد أوشك انتفا أن نزرا\nومثل كاد في الأصح كربا ... وترك أن مع ذي الشروع وجبا\nكأنشأ السائق يحدو وطفق ... كذا جعلت وأخذت وعلق\nواستعملوا مضارعا لأوشكا ... وكاد لا غير وزادوا موشكا\nبعد عسى اخلولق أوشك قد يرد ... غنى بأن يفعل عن ثان فقد\nوجردن عسى أو ارفع مضمرا ... بها إذا اسم قبلها قد ذكرا\nوالفتح والكسر أجز في السين من ... نحو عسيت وانتفا الفتح زكن"},{"id":"alfiyya:13","bookId":"alfiyya","type":"section","seq":13,"chapter":"مقدمة المؤلف","title":"إن وأخواتها","page":"ج1 ص21","text":"لان أن ليت لكن لعل ... كأن عكس ما لكان من عمل\nكإن زيدا عالم بأني ... كفء ولكن ابنه ذو ضعن\nوراع ذا الترتيب إلا في الذي ... كليت فيها أو هنا غير البذي\nوهمز إن افتح لسد مصدر ... مسدها وفي سوى ذاك اكسر\nفاكسر في الابتدا وفي بدء صله ... وحيث إن ليمين مكمله\nأو حكيت بالقول أو حلت محل ... حال كزرته وإني ذو أمل\nوكسروا من بعد فعل علقا ... باللام كاعلم إنه لذو تقى\nبعد إذا فجاءة أو قسم ... لا لام بعده بوجهين نمي\nمع تلوفا الجزا وذا يطرد ... في نحو خير القول إني أحمد\nوبعد ذات الكسر تصحب الخبر ... لام ابتداء نحو إني لوزر\nولا يلي ذي اللام ما قد نفيا ... ولا من الأفعال ما كرضيا\nوقد يليها مع قد كإن ذا ... لقد سما على العدا مستحوذا\nوتصحب الواسط معمول الخبر ... والفصل واسما حل قبله الخبر\nووصل ما بذي الحروف مبطل ... إعمالها وقد يبقى العمل\nوجائز رفعك معطوفا على ... منصوب إن بعد أن تستكملا\nوألحقت بإن لكن وأن ... من دون ليت ولعل وكأن\nوخففت إن فقل العمل ... وتلزم اللام إذا ما تمهل\nوربما استغني عنها إن بدا ... ما ناطق أراده معتمدا\nوالفعل إن لم يك ناسخا فلا ... تلفيه غالبا بإن ذي موصلا\nوإن تخفف أن فاسمها استكن ... والخبر اجعل جملة من بعد أن\nوإن يكن فعلا ولم يكن دعا ... ولم يكن تصريفه ممتنعا\nفالأحسن الفصل بقد أو نفي أو ... تنفيس أو ولو قليل ذكر لو\nوخففت كأن أيضا فنوي ... منصوبها وثابتا أيضا روي"},{"id":"alfiyya:14","bookId":"alfiyya","type":"section","seq":14,"chapter":"مقدمة المؤلف","title":"لا التي لنفى الجنس","page":"ج1 ص22","text":"عمل إن اجعل للا في نكره ... مفردة جاءتك أو مكررة\nفانصب بها مضافا أو مضارعه ... بعد ذاك الخبر اذكر رافعه\nووكب المفرد فاتحا كلا ... حول ولا قوة والثان اجعلا\nمرفوعا أو منصوبا أو مركبا ... وإن رفعت أولا لا تنصبا\nومفردا نعتا لمبني يلي ... فافتح أو انصبن أو ارفع تعدل\nوغير ما يلي وغير المفرد ... لا تبن وانصبه أو الرفع اقصد\nوالعطف إن لم تتكرر لا احكما ... له بما للنعت ذي الفصل انتمى\nوأعط لا مع همزة استفهام ... ما تستحق دون الاستفهام\nوشاع في ذا الباب إسقاط الخبر ... إذا المراد مع سقوطه ظهر"},{"id":"alfiyya:15","bookId":"alfiyya","type":"section","seq":15,"chapter":"مقدمة المؤلف","title":"ظل وأخواتها","page":"ج1 ص23","text":"انصب بفعل القلب جزأي ابتدا ... أعني رأى خال علمت وجدا\nظن حسبت وزعمت مع عد ... حجا درى وجعل الذ كاعتقد\nوهب تعلم والتي كصيرا ... أيضا بها انصب مبتدأ وخبرا\nوخص بالتعليق والإلغاء ما ... من قبل هب والأمر هب قد ألزما\nكذا تعلم ولغير الماض من ... سواهما اجعل كل ماله زكن\nوجوز الإلغاء لا في الابتدا ... وانو ضمير الشان أولام ابتدا\nفي موهم إلغاء ما تقدما ... والتزم التعليق قبل نفي ما\nوإن ولا لام ابتداء أو قسم ... كذا والاستفهام ذا له انحتم\nلعلم عرفان وظن تهمه ... تعدية لواحد ملتزمه\nولرأى الرؤيا اثم ما لعلما ... طالب مفعولين من قبل انتمى\nولا تجز هنا بلا دليل ... سقوط مفعولين أو مفعول\nوكتظن اجعل تقول إن ولي ... مستفهما به ولم ينفصل\nبغير ظرف أو كظرف أو عمل ... وإن ببعض ذي فصلت يحتمل\nوأجري القول كظن مطلقا ... عند سليم نحو قل ذا مشفقا"},{"id":"alfiyya:16","bookId":"alfiyya","type":"section","seq":16,"chapter":"مقدمة المؤلف","title":"أعلم وأرى","page":"ج1 ص24","text":"لى ثلاثة رأى وعلما ... عدوا إذا صار أرى وأعلما\nوما لمفعولي علمت مطلقا ... للثان والثالث أيضا حققا\nوإن تعديا لواحد بلا ... همز فلاثنين به توصلا\nوالثان منهما كثاني اثني كسا ... فهو به في كل حكم ذو ائتسا\nوكأرى السابق نبا أخبرا ... حدث أنبأ كذاك خبرا"},{"id":"alfiyya:17","bookId":"alfiyya","type":"section","seq":17,"chapter":"مقدمة المؤلف","title":"الفاعل","page":"ج1 ص24","text":"الفاعل الذي كمرفوعي أتى ... زيد منيرا وجهه نعم الفتى\nوبعد فعل فاعل فإن ظهر ... فهو وإلا فضمير استتر\nوجرد الفعل إذا ما أسندا ... لاثنين أو جمع كفاز الشهدا\nوقد يقال سعدا وسعدوا ... والفعل للظاهر بعد مسند\nويرفع الفاعل فعل أضمرا ... كمثل زيد في جواب من قرا\nوتاء تأنيث تلي الماضي إذا ... كان لأنثى كأبت هند الأذى\nوإنما تلزم فعل مضمر ... متصل أو مفهم ذات حر\nوقد يبيح الفصل ترك التاء في ... نحو أتى القاضي بنت الواقف\nوالحذف مع فصل بإلا فضلا ... كما زكا إلا فتاة ابن العلا\nوالحذف قد ياتي بلا فصل ومع ... ضمير ذي المجاز في شعر وقع\nوالتاء مع جمع سوى السالم من ... مذكر كالتاء مع إحدى اللبن\nوالحذف في نعم الفتاة استحسنوا ... لأن قصد الجنس فيه بين\nوالأصل في الفاعل أن يتصلا ... والأصل في المفعول أن ينفصلا\nوقد يجاء بخلاف الأصل ... وقد يجى المفعول قبل الفعل\nوأخر المفعول إن لبس حذر ... أو أضمر الفاعل غير منحصر\nوما بإلا أو بإنما انحصر ... أخر وقد يسبق إن قصد ظهر\nوشاع نحو خاف ربه عمر ... وشذ نحو زان نوره الشجر"},{"id":"alfiyya:18","bookId":"alfiyya","type":"section","seq":18,"chapter":"مقدمة المؤلف","title":"النائب عن الفاعل","page":"ج1 ص25","text":"ينوب مفعول به عن فاعل ... فيما له كنيل خير نائل\nفأول الفعل اضممن والمتصل ... بالآخر اكسر في مضي كوصل\nواجعله من مضارع منفتحا ... كينتحي المقول فيه ينتحى\nوالثاني التالي تاالمطاوعة ... كالأول اجعله بلا منازعه\nوثالث الذي بهمز الوصل ... كالأول اجعلنه كاستحلى\nواكسر أو اشمم فاثلاثي أعل ... عينا وضم جاكبوع فاحتمل\nوإن بشكل خيف لبس يجتنب ... وما لباع قد يرى لنحو حب\nوما لفا باع لما العين تلي ... في اختار وانقاد وشبه ينجلي\nوقابل من ظرف أو من مصدر ... أو حرف جر بنيابة حري\nولا ينوب بعض هذي إن وجد ... في اللفظ مفعول به وقد يرد\nوباتفاق قد ينوب الثان من ... باب كسا فيما التباسه أمن\nفي باب ظن وأرى المنع اشتهر ... ولا أرى منعا إذا القصد ظهر\nوما سوى النائب مما علقا ... بالرافع النصب له محققا"},{"id":"alfiyya:19","bookId":"alfiyya","type":"section","seq":19,"chapter":"مقدمة المؤلف","title":"اشتغال العامل عن المعمول","page":"ج1 ص26","text":"إن مضمر إسم سابق فعلا شغل ... عنه بنصب لفظه أو المحل\nفالسابق انصبه بفعل أضمرا ... حتما موافق لما قد أظهرا\nوالنصب حتم إن تلا السابق ما ... يختص بالفعل كإن وحيثما\nوإن تلا السابق ما بالابتدا ... يختص فالرفع التزمه أبدا\nكذا إذا الفعل تلا ما لم يرد ... ما قبل معمولا لما بعد وجد\nواختير نصب قبل فعل ذي طلب ... وبعد ما إيلاؤه الفعل غلب\nوبعد عاطف بلا فصل على ... معمول فعل مستقر أولا\nوإن تلا المعطوف فعلا مخبرا ... به عن اسم فاعطفن مخيرا\nوالرفع في غير الذي مر رجح ... فما أبيح افعل ودع ما لم يبح\nوفصل مشغول بحرف جر ... أو بإضافة كوصل يجري\nوسو في ذا الباب وصفا ذا عمل ... بالفعل إن لم يك مانع حصل\nوعلقه حاصلة بتابع ... كعلقة بنفس الإسم الواقع"},{"id":"alfiyya:20","bookId":"alfiyya","type":"section","seq":20,"chapter":"مقدمة المؤلف","title":"تعدي الفعل ولزومه","page":"ج1 ص27","text":"علامة الفعل المعدى أن تصل ... هما غير مصدر به نحو عمل\nفانصب به مفعوله إن لم ينب ... عن فاعل نحو تدبرت الكتب\nولازم غير المعدى وحتم ... لزوم أفعال السجايا كنهم\nكذا افعلل والمضاهي اقعنسسا ... وما اقتضى نظافة أو دنسا\nأو عرضا أو طاوع المعدى ... لواحد كمده فامتدا\nوعد لازما بحرف جر ... وإن حذف فالنصب للمنجر\nنقلا وفي أن وأن يطرد ... مع أمن لبس كعجبت أن يدوا\nوالأصل سبق فاعل معنى كمن ... من ألبسن من زاركم نسج اليمن\nويلزم الأصل لموجب عرا ... وترك ذاك الأصل حتما قد يرى\nوحذف فضلة أجر إن لم يضر ... كحذف ما سيق جوابا أو حصر\nويحذف الناصبها إن علما ... وقد يكون حذفه ملتزما"},{"id":"alfiyya:21","bookId":"alfiyya","type":"section","seq":21,"chapter":"مقدمة المؤلف","title":"التنازع في العمل","page":"ج1 ص28","text":"إن عاملان اقتضيا في اسم عمل ... قبل فللواحد منهما العمل\nوالثاني أولى عند أهل البصره ... واختار عكسا غيرهم ذا أسره\nوأعمل المهمل في ضمير ما ... تنازعاه والتزم ما التزما\nكيحسنان ويسيء ابناكا ... وقد بغى واعتديا عبداكا\nولا تجيء مع أول قد أهملا ... بمضمر لغير رفع أو هلا\nبل حذفه الزم إن يكن غير خبر ... وأخرنه إن يكن هو الخبر\nوأظهر ان يكن ضمير خبرا ... لغير ما يطابق المفسرا\nنحو أظن ويظناني أخا ... زيدا وعمرا أخوين في الرخا"},{"id":"alfiyya:22","bookId":"alfiyya","type":"section","seq":22,"chapter":"مقدمة المؤلف","title":"المفعول المطلق","page":"ج1 ص29","text":"المصدر اسم ما سوى الزمان من ... مدلولي الفعل كأمن من أمن\nبمثله أو فعل أو وصف نصب ... وكونه أصلا لهذين انتخب\nتوكيدا او نوعا يبين أو عدد ... كسرت سيرتين سير ذي رشد\nوقد ينوب عنه ما عليه دل ... كجد كل الجد وافرح الجذل\nوما لتوكيد فوحد ابدا ... وثن واجمع غيره وأفردا\nوحذف عامل المؤكد امتنع ... وفي سواه لدليل متسع\nوالحذف حتم مع آت بدلا ... من فعله كندلا اللذكا ندلا\nوما لتفصيل كإما منا ... عامله يحذف حيث عنا\nكذا مكرر وذز حصر ورد ... نائب فعل لاسم عين استند\nومنه ما يدعونه مؤكدا ... لنفسه أو غيره فالمبتدا\nنحو له على ألف عرفا ... والثان كابني أنت حقا صرفا\nكذاك ذو التشبيه بعد جمله ... كلي بكا بكاء ذات عضله"},{"id":"alfiyya:23","bookId":"alfiyya","type":"section","seq":23,"chapter":"مقدمة المؤلف","title":"المفعول له","page":"ج1 ص29","text":"ينصب مفعولا له المصدر إن ... أبان تعليلا كحد شكرا ودن\nوهو بما يعمل فيه متخذ ... وقتا وفاعلا وإن شرط فقد\nفاجرره بالحرف وليس يمتنع ... مع الشروط كلزهد ذا قنع\nوقل أن يصحبها المجرد ... والعكس في مصحوب ال وأنشدوا\n\"لا أقعد الجبن عن الهيجاء ... ولو توالت زمر الأعداء\""},{"id":"alfiyya:24","bookId":"alfiyya","type":"section","seq":24,"chapter":"مقدمة المؤلف","title":"المفعول فيه وهو المسمى ظرفا","page":"ج1 ص30","text":"الظرف وقت أو مكان ضمنا ... في باطراد كهنا امكث أزمنا\nفانصبه ب الواقع فيه مظهرا ... كان وإلا فانوه مقدرا\nوكل وقت قابل ذاك وما ... يقبله المكان إلا مبهما\nنحو الجهات والمقادير وما ... صيغ من الفعل كمرمى من رمى\nوشرط كون ذا مقيسا أن يقع ... ظرفا لما في أصله معه اجتمع\nوما يرى ظرفا وغير ظرف ... فذاك ذو تصرف في العرف\nوغير ذي التصرف الذي لزم ... ظرفية أو شبهها من الكلم\nوقد ينوب عن مكان مصدر ... وذاك في ظرف الزمان يكثر"},{"id":"alfiyya:25","bookId":"alfiyya","type":"section","seq":25,"chapter":"مقدمة المؤلف","title":"المفعول معه","page":"ج1 ص30","text":"ينصب تالي الواو مفعولا معه ... في نحو سيري والطريق مسرعه\nبما من الفعل وشبهه سبق ... ذا النصب لا بالواو في القول الأحق\nوبعد ما استفهام او كيف نصب ... بفعل كون مضمر بعض العرب\nوالعطف إن يمكن بلا ضعف أحق ... والنصب مختار لدى ضعف النسق\nوالنصب إن لم يجز العطف يجب ... أو أعتقد إضمار عامل تصب"},{"id":"alfiyya:26","bookId":"alfiyya","type":"section","seq":26,"chapter":"مقدمة المؤلف","title":"الاستثناء","page":"ج1 ص31","text":"ما استثنيت إلا مع تمام ينتصب ... وبعد نفي أو كنفي أنتخب\nإتباع ما اتصل وانصب ما انقطع ... وعن تميم فيه إبدال وقع\nوغير نصب سابق في النفي قد ... يأتي ولكن نصبه اختر إن ورد\nوإن يفرغ سابق إلا لما ... بعد يكن كما لو إلا عدما\nوألغ إلا ذات توكيد كلا ... تمرر بهم إلا الفتى إلا العلا\nوإن تكرر لا لتوكيد فمع ... تفريغ التأثير بالعامل دع\nفي واحد مما بإلا استثني ... وليس عن نصب سواه مغني\nودون تفريغ مع التقدم ... نصب الجميع احكم به والتزم\nوانصب لتأخير وجيء بواحد ... منها كما لو كان دون زائد\nكلم يفوا إلا امرؤ إلا علي ... وحكمها في القصد حكم الأول\nواستثن مجرورا بغير معربا ... بما لمستثنى بألا نسبا\nولسوى سوى سواء اجعلا ... على الأصح ما لغير جعلا\nواستثن ناصبا بليس وخلا ... وبعدا وبيكون بعد لا\nواجرر بسابقي يكون إن ترد ... وبعد ما انصب وانجرار قد يرد\nوحيث جرا فهما حرفان ... كما هما إن نصبا فعلان\nوكخلا حاشا ولا تصحب ما ... وقيل حاش وحشا فاحفظهما"},{"id":"alfiyya:27","bookId":"alfiyya","type":"section","seq":27,"chapter":"مقدمة المؤلف","title":"الحال","page":"ج1 ص32","text":"لحال وصف فضلة منتصب ... مفهم في حال كفردا أذهب\nوكونه منتقلا مشتقا ... يغلب لكن ليس مستحقا\nويكثر الجمود في سعر وفي ... مبدي تأول بلا تكلف\nكبعه مدا بكذا يدا بيد ... وكر زيد أسدا أي كأسد\nوالحال إن عرف لفظا فاعتقد ... تنكيره معنى كوحدك اجتهد\nومصدر منكر حالا يقع ... بكثرة كبغتة زيد طلع\nولم ينكر غالبا ذو الحال إن ... لم يتأخر أو يخصص أي يبن\nمن بعد نفي او مضاهيه كلا ... يبغ امرؤ على امرىء مستسهلا\nوسبق حال ما بحرف جر قد ... أبوا ولا أمنعه فقد ورد\nولا تجز حالا من المضاف له ... إلا إذا اقتضى المضاف عمه\nأو كان جزء ماله أضيفا ... أو مثل جزئه فلا تحيفا\nوالحال إن ينصب بفعل صرفا ... أو صفة أشبهت المصرفا\nفجائز تقديمه كمسرعا ... ذا راحل ومخلصا زيد دعا\nوعامل ضمن معنى الفعل لا ... حروفه مؤخرا لن يعملا\nكتلك ليت وكأن وندر ... نحو سعيد مستقرا في هجر\nونحو زيد مفردا أنفع من ... عمرو معانا مستجاز لن يهن\nوالحال قد يجيء ذا تعدد ... لمفرد فاعلم وغير مفرد\nوعامل الحال بها قد أكدا ... في نحو لا تعث في الأرض مفسدا\nوإن تؤكد جملة فمضمر ... عاملها ولفظها يؤخر\nوموضع الحال تجيء جمله ... كجاء زيد وهو ناو رحله\nوذات بدء بمضارع ثبت ... حوت ضميرا ومن الواو خلت\nوذات واو بعدها انو مبتدا ... له المضارع اجعلن مسندا\nوجملة الحال سوى ما قدما ... بواو او بمضمر أو بهما\nوالحال قد يحذف ما فيها عمل ... وبعض ما يحذف ذكره حظل\nالتميز:\nإسم بمعنى من مبين نكره ... ينصب تمييزا بما قد فسره\nكشبر ارضا وقفيز برا ... ومنوين عسلا وتمرا\nوبعد ذي وشبهها اجرره إذا ... أضفتها كمد حنطة غذا\nوالنصب بعد ما أضيف وجبا ... إن كان مثل ملء الأرض ذهبا\nوالفاعل المعنى انصبن بأفعلا ... مفضلا كأنت أعلى منزلا\nوبعد كل ما اقتضى تعجبا ... ميز كأكرم بأبي بكر أبا\nواجرر بمن إن شئت غير ذي العدد ... والفاعل المعني كطب نفسا تفد\nوعامل"},{"id":"alfiyya:28","bookId":"alfiyya","type":"section","seq":28,"chapter":"مقدمة المؤلف","title":"التمييز","page":"ج1 ص34","text":"قدم مطلقا ... والفعل ذو التصريف نزرا سبقا"},{"id":"alfiyya:29","bookId":"alfiyya","type":"section","seq":29,"chapter":"مقدمة المؤلف","title":"حروف الجر","page":"ج1 ص34","text":"هاك حروف الجر وهي من إلى ... حتى خلا حاشا عدا في عن على\nمذ منذ رب اللام كي واو وتا ... والكاف والبا ولعل ومتى\nبالظاهر اخصص منذ مذ وحتى ... والكاف والواو ورب والتا\nواخصص بمذ ومنذ وقتا وبرب ... منكرا والتاء لله ورب\nوما رووا من نحو ربه فتى ... نزر كذا كها ونحوه أتى\nبعض وبين وابتدئ في الأمكنة ... بمن وقد تأتي لبدء الأزمنة\nوزيد في نفي وشبهه فجر ... نكرة كما لباغ من مفر\nللآنتها حتى ولام والى ... ومن وباء يفهمان بدلا\nواللام للملك وشبهه وفي ... تعدية أيضا وتعليل قفي\nوزيد والظرفية استبن ببا ... وفي وقد يبينان السببا\nبالبا استعن وعد عوض ألصق ... ومثل مع ومن وعن بها انطلق\nعلى للاستعلا ومعنى في وعن ... بعن تجاوزا عنى من قد فطن\nوقد تجى موضع بعد وعلى ... كما على موضع عن قد جعلا\nشبه بكاف وبها التعليل قد ... يعنى وزائدا لتوكيد ورد\nواستعمل اسما وكذا عن وعلى ... من أجل ذا عليهما من دخلا\nومذ ومنذ اسمان حيث رفعا ... أو أوليا الفعل كجئت مذ دعا\nوإن يجرا في مضي فكمن ... هما وفي الحضور معنى في استبن\nوبعد من وعن وباء زيد ما ... فلم يعق عن عمل قد علما\nوزيد بعد رب والكاف فكف ... وقد يليهما وجر لم يكف\nوحذفت رب فجرت بعد بل ... وألفاوبعد الواو شاع ذا العمل\nوقد يجر بسوى رب لدى ... حذف وبعضه يرى مطردا"},{"id":"alfiyya:30","bookId":"alfiyya","type":"section","seq":30,"chapter":"مقدمة المؤلف","title":"الإضافة","page":"ج1 ص36","text":"نونا تلي الإعراب أو تنوينا ... مما تضيف احذف كطور سينا\nوالثاني اجرر وانو من أو في إذا ... لم يصلح إلا ذاك واللام خذا\nلما سوى ذينك واخصص أولا ... أو أعطه التعريف بالذي تلا\nوإن يشابه المضاف يفعل ... وصفا فعن تنكيره لا يعزل\nكرب راجينا عظيم الأمل ... مروع القلب قليل الحيل\nوذي الإضافة اسمها لفظية ... وتلك محضة ومعنوية\nووصل أل بذا المضاف مغتفر ... إن وصلت بالثاني كالجعد الشعر\nأو بالذي له أضيف الثاني ... كزيد الضارب رأس الجاني\nوكانها في الوصف كاف إن وقع ... مثنى أو جمعا سبيله اتبع\nوربما أكسب ثان أولا ... تأنيثا ان كان الحذف موهلا\nولا يضاف اسم لما به اتحد ... معنى وأول موهما إذا ورد\nوبعض الأسماء يضاف أبدا ... وبعض ذا قد يأت لفظا مفردا\nوبعض ما يضاف حتما امتنع ... إيلاؤه اسما ظاهرا حيث وقع\nكوحد لبى ودوالي سعدي ... وشذ إيلاء يدي للبى\nوألزموا إضافة الى الجمل ... حيث وإذ وإن ينون يحتمل\nإفراد إذ وما كإذ معنى كإذ ... أضف جوازا نحو حين جانبذ\nوابن أو اعرب ما كإذ قد أجريا ... واختر بنا متلو فعل بنيا\nوقبل فعل معرب أو مبتدا ... أعرب ومن بنى فلن يفندا\nوألزموا إذا إضافة الى ... جمل الافعال كهن إذا اعتلى\nلمفهم اثنين معرف بلا ... تفرق أضيف كلتا وكلا\nولا تضف لمفرد معرف ... أيا وإن كررتها فأضف\nأوتنو الأجزا واخصص بالمعرفة ... موصولة أيا وبالعكس الصفه\nوإن تكن شرطا أو استفهاما ... فمطلقا كمل بها الكلاما\nوالزموا إضافة لدن فجر ... ونصب غدوة بهما عنهم ندر\nومع مع فيها قليل ونقل ... فتح وكسر لسكون يتصل\nواضمم بناء غيرا ان عدمت ما ... له أضيف ناويا ما عدما\nقبل كغير بعد حسب أول ... ودون والجهات أيضا وعل\nوأعربوا نصبا إذا ما نكرا ... قبلا وما من بعده قد ذكرا\nوما يلي المضاف يأتي خلفا ... عنه في الاعراب إذا ما حذفا\nوربما جروا الذي أبقوا كما ... قد كان قبل حذف ما تقدما\nلكن بشرط أن يكون ما حذف ... مماثلا لما عليه قد عطف\nويحذف الثاني فيبقى الأول ... كحاله إذا به يتصل\nبشرط عطف وإضافة إلى ... مثل الذي له أضفت الأولا\nفصل مضاف شبه فعل ما نصب ... مفعولا أو ظرفا أجز ولم يعب\nفصل يمين واضطرارا وجدا ... بأجنبي أو بنعت أو ندا"},{"id":"alfiyya:31","bookId":"alfiyya","type":"section","seq":31,"chapter":"مقدمة المؤلف","title":"المضاف الى ياء المتكلم","page":"ج1 ص38","text":"...\nلمضاف الى ياء المتكلم:\nآخر ما أضيف لليا اكسر إذا ... لم يك معتلا كرام وقذا\nأو يك كابنين وزيدين فذي ... جميعها اليا بعد فتحها احتذي\nوتدغم اليا فيه والواو وإن ... ما قبل واو ضم فاكسره يهن\nوألفا سلم وفي المقصور عن ... هذيل انقلابها ياء حسن"},{"id":"alfiyya:32","bookId":"alfiyya","type":"section","seq":32,"chapter":"مقدمة المؤلف","title":"إعمال المصدر","page":"ج1 ص38","text":"بفعله المصدر ألحق في العمل ... مضافا أو مجردا أو مع أل\nإن كان فعل مع أن أو ما يحل ... محله ولاسم مصدر عمل\nوبعد جره الذي أضيف له ... كمل بنصب أو برفع عمله\nوجر ما يتبع ما جر ومن ... راعى في الاتباع المحل فحسن"},{"id":"alfiyya:33","bookId":"alfiyya","type":"section","seq":33,"chapter":"مقدمة المؤلف","title":"إعمال اسم الفاعل","page":"ج1 ص39","text":"كفعله اسم فاعل في العمل ... إن كان عن مضيه بمعزل\nوولي استفهاما أو حرف ندا ... أو نفيا او جاصفة أو مسندا\nوقد يكون نعت محذوف عرف ... فيستحق العمل الذي وصف\nوإن يكن صلة ففي المضي ... وغيره إعماله قد ارتضي\nفعال او مفعال او فعول ... في كثرة عن فاعل بديل\nفيستحق ماله من عمل ... وفي فعيل قل ذا وفعل\nوما سوى المفرد مثله جعل ... في الحكم والشروط حيثما عمل\nوانصب بذي الإعمال تلوا واخفض ... وهو لنصب ما سواه مقتضي\nواجرر أو انصب تابع الذي انخفض ... كمبتغي جاه ومالا من نهض\nوكل ما قرر لاسم فاعل ... يعطى اسم مفعول بلا تفاضل\nفهو كفعل صيغ للمفعول في ... معناه كالمعطى كفافا يكتفي\nوقد يضاف ذا الى اسم مرتفع ... معنى كمحمود المقاصد الورع"},{"id":"alfiyya:34","bookId":"alfiyya","type":"section","seq":34,"chapter":"مقدمة المؤلف","title":"أبنية المصادر","page":"ج1 ص39","text":"فعل قياس مصدر المعدى ... من ذي ثلاثة كرد ردا\nوفعل اللازم بابه فعل ... كفرح وكجوى وكشلل\nوفعل اللازم مثل قعدا ... له فعول باطراد كغدا\nما لم يكن مستوجبا فعالا ... أو فعلانا فادر أو فعالا\nفأول لذي امتناع كأبى ... والثان للذي اقتضى تقلبا\nللدا فعال أو لصوت وشمل ... سيرا وصوتا الفعيل كصهل\nفعولة فعالة لفعلا ... كسهل الأمر وزيد جزلا\nوما أتى محالفا لما مضى ... قبابه النقل كسخط ورضا\nوغير ذي ثلاثة مقيس ... مصدره كقدس التقديس\nوزكه تزكية وأجملا ... إجمال من تجملا تجملا\nواستعذ استعاذة ثم أقم ... إقامة وغالبا ذا التا التزم\nومايلي الآخر مد وافتحا ... مع كسر تلو الثان مما افتتحا\nبهمز وصل كاصطفى وضم ما ... يربع في أمثال قد تلملما\nفعلال او فعللة لفعللا ... واجعل مقيسا ثانيا لا أولا\nلفاعل الفعال والمفاعله ... وغير ما مر السماع عادلة\nوفعلة لمرة كجلسه ... وفعلة لهيئة كجلسه\nفي غير ذي الثلاث بالتا المره ... وشذ فيه هيئة كالخمرة"},{"id":"alfiyya:35","bookId":"alfiyya","type":"section","seq":35,"chapter":"مقدمة المؤلف","title":"أبنية الفاعلين والمفعولين (والصفات المشبهات بها","page":"ج1 ص41","text":"...\nأبنية أسماء الفاعلين والمفعولين\nوالصفات المشبهة بها:\nكفاعل صغ اسم فاعل إذا ... من ذي ثلاثة يكون كغذا\nوهو قليل في فعلت وفعل ... غير معدى بل قياسه فعل\nوأفعل فعلان نحو أشر ... ونحو صديان ونحو الأجهر\nوفعل اولى وفعيل بفعل ... كالضخم والجميل والفعل جمل\nوأفعل فيه قليل وفعل ... وبسوى الفاعل قد يغنى فعل\nوزنة المضارع اسم فاعل ... من غير ذي الثلاث كالمواصل\nمع كسر متلو الأخير مطلقا ... وضم ميم زائد قد سبقا\nوإن فتحت منه ما كان انكسر ... صار اسم مفعول كمثل المنتظر\nوفي اسم مفعول الثلاثي اطرد ... زنة مفعول كآت من قصد\nوناب نقلا عنه ذو فعيل ... نحو فتاة أو فتى كحيل"},{"id":"alfiyya:36","bookId":"alfiyya","type":"section","seq":36,"chapter":"مقدمة المؤلف","title":"الصفة المشبهة باسم الفاعل","page":"ج1 ص41","text":"صفة استحسن جر فاعل ... معنى بها المشبهة اسم الفاعل\nوصوغها من لازم لحاضر ... كطاهر القلب جميل الظاهر\nوعمل اسم فاعل المعدى ... لها على الحد الذي قد حدا\nوسبق ما تعمل فيه مجتنب ... وكونه ذا سببية وجب\nفارفع بها وانصب وجر مع أل ... ودون أل مصحوب أل وما اتصل\nبها مضافا أو مجردا ولا ... تجرر بها مع أل سما من أل خلا\nومن إضافة لتاليها وما ... لم يخل فهو بالجواز وسما"},{"id":"alfiyya:37","bookId":"alfiyya","type":"section","seq":37,"chapter":"مقدمة المؤلف","title":"التعجب","page":"ج1 ص42","text":"بأفعل انطق بعد ما تعجبا ... أو جيء بأفعل مجرور بباء\nوتلو أفعل انصبنه كما ... أوفى خليلنا وأصدق بهما\nوحذف ما منه تعجبت استبح ... إن كان عند الحذف معناه يضح\nوفي كلا الفعلين قدما لزما ... منع تصرف بحكم حتما\nوصغهما من ذي ثلاث صرفا ... قابل فضل تم غير ذي انتفا\nوغير ذي وصف يضاهي أشهلا ... وغير سالك سبيل فعلا\nوأشدد أو أشد أو شبههما ... يخلف ما بعض الشروط عدما\nومصدر العادم بعد ينتصب ... وبعد أفعل جره بالبا يجب\nوبالندور احكم لغير ما ذكر ... ولا تقس على الذي منه أثر\nوفعل هذا الباب لن يقدما ... معموله ووصله به الزما\nوفضله بظرف او بحرف جر ... مستعمل والخلف في ذاك استقر"},{"id":"alfiyya:38","bookId":"alfiyya","type":"section","seq":38,"chapter":"مقدمة المؤلف","title":"نعم وبئس وما جرى مجراهما","page":"ج1 ص43","text":"فعلان غير متصرفين ... نعم وبئس رافعان اسمين\nمقارني أل أو مضافين لما ... قارنهما كنعم عقبى الكرما\nويرفعان مضمرا يفسره ... مميز كنعم قوما معشره\nوجمع تمييز وفاعل ظهر ... فيه خلاف عنهم قد اشتهر\nوما مميز وقيل فاعل ... في نحو نعم ما يقول الفاضل\nويذكر المخصوص بعد مبتدا ... أو خبر اسم ليس يبدو أبدا\nوإن يقدم مشعر به كفى ... كالعلم نعم المقتنى والمقتفى\nواجعل كبئس ساء واجعل فعلا ... من ذي ثلاثة كنعم مسجلا\nومثل نعم حبذا الفاعل ذا ... وإن ترد ذما فقل لا حبذا\nوأول ذا المخصوص أيا كان لا ... تعدل بذا فهو يضاهي المثلا\nوما سوى ذا ارفع بحب أو فجر ... باليا ودون ذا انضمام الحا كثر\nأفعل التفضيل:\nصغ من مصوغ منه للتعجب ... أفعل للتفضيل وأب اللذ أبي\nوما به إلى تعجب وصل ... لمانع به الى التفضيل صل\nو"},{"id":"alfiyya:39","bookId":"alfiyya","type":"section","seq":39,"chapter":"مقدمة المؤلف","title":"أفعل التفضيل","page":"ج1 ص44","text":"صله أبدا ... تقديرا أو لفظا بمن إن جردا\nوإن لمنكور يضف أو جردا ... ألزم تذكيرا وأن يوحدا\nوتلو أل طبق وما لمعرفه ... أضيف ذو وجهين عن ذي معرفه\nهذا إذا نويت معنى من وإن ... لم تنو فهو طبق ما به قرن\nوإن تكن بتلو من مستفهما ... فلهما كن أبدا مقدما\nكمثل ممن أنت خير ولدى ... إخبار التقديم نزرا وردا\nورفعه الظاهر نزر ومتى ... عاقب فعلا فكثيرا ثبتا\nكلن ترى في الناس من رفيق ... أولى به الفضل من الصديق"},{"id":"alfiyya:40","bookId":"alfiyya","type":"section","seq":40,"chapter":"مقدمة المؤلف","title":"النعت","page":"ج1 ص44","text":"يتبع في الإعراب الأسماء الأول ... نعت وتوكيد وعطف وبدل\nفالنعت تابع متم ما سبق ... بوسمه أو وسم ما به اعتلق\nوليعط في التعريف والتنكير ما ... لما تلا كامرر بقوم كرما\nوهو لدى التوحيد والتذكير أو ... سواهما كالفعل فاقف ما قفوا\nوانعت بمشتق كصعب وذرب ... وشبهه كذا وذي والمنتسب\nونعتوا بجملة منكرا ... فأعطيت ما أعطيته خبرا\nوامنع هنا إيقاع ذات الطلب ... وإن أتت فالقول أضمر تصب\nونعتوا بمصدر كثيرا ... فالتزموا الإفراد والتذكيرا\nونعت غير واحد إذا اختلف ... فعاطفا فرقه لا إذا انتلف\nونعت معمولي وحيدي معنى ... وعمل أتبع بغير استثنا\nوإن نعوت كثرت وقد تلت ... مفتقرا لذكرهن أتبعت\nواقطع أو اتبع إن يكن معينا ... بدونها أو بعضها اقطع معلنا\nوارفع او انصب إن قطعت مضمرا ... مبتدأ أوناصبا لن يظهرا\nوما من المنعوت والنعت عقل ... يجوز حذفه وفي النعت يقل"},{"id":"alfiyya:41","bookId":"alfiyya","type":"section","seq":41,"chapter":"مقدمة المؤلف","title":"التوكيد","page":"ج1 ص45","text":"بالنفس أو بالعين الاسم اكدا ... مع ضمير طابق المؤكدا\nواجمعهما بأفعل إن تبعا ... ماليس واحدا تكن متبعا\nكلا اذكر في الشمول وكلا ... كلتا جميعا بالضمير موصلا\nواستعملوا أيضا ككل فاعله ... من عم في التوكيد مثل النافلة\nوبعد كل أكدوا بأجمعا ... جمعاء أجمعين ثم جمعا\nودون كل قد يجىء أجمع ... جمعاء أجمعون ثم جمع\nوإن يفد توكيد منكور قبل ... وعن نحاة البصرة المنع شمل\nواغن بكلتا في مثنى وكلا ... عن وزن فعلاء ووزن أفعلا\nوإن تؤكد الضمير المتصل ... بالنفس والعين فبعد المنفصل\nعنيت ذا الرفع وأكدوا بما ... سواهما والقيد لن يلتزما\nوما من التوكيد لفظي يجي ... مكررا كقولك ادرجي ادرجي\nولا تعد لفظ ضمير متصل ... إلا مع الفظ الذي به وصل\nكذا الحروف غير ما تحصلا ... به جواب كنعم وكبلى\nومضمر الرفع الذي قد انفصل ... أكد به كل ضمير اتصل"},{"id":"alfiyya:42","bookId":"alfiyya","type":"section","seq":42,"chapter":"مقدمة المؤلف","title":"العطف","page":"ج1 ص46","text":"العطف إما ذو بيان أو نسق ... والغرض الآن بيان ما سبق\nفذو البيان تابع شبه الصفه ... حقيقة القصد به منكشفه\nفأولينه من وفاق الأول ... ما من وفاق الأول النعت ولي\nفقد يكونان منكرين ... كما يكونان معرفين\nوصالحا لبدلية يرى ... في غير نحو يا غلام يعمرا\nونحو بشر تابع البكري ... وليس أن يبدل بالمرضي"},{"id":"alfiyya:43","bookId":"alfiyya","type":"section","seq":43,"chapter":"مقدمة المؤلف","title":"عطف النسق","page":"ج1 ص47","text":"تال بحرف متبع عطف النسق ... كاخصص بود وثناء من صدق\nفالعطف مطلقا بواو ثم فا ... حتى أم أو كفيك صدق ووفا\nوأتبعت لفظا فحسب بل ولا ... لكن كلم يبد امرؤ لكن طلا\nفاعطف بواو سابقا أو لاحقا ... في الحكم أو مصاحبا موافقا\nواخصص بهاعطف الذي لا يغني ... متبوعة كاصطف هذا وابني\nوالفاء للترتيب باتصال ... وثم للترتيب بانفصال\nواخصص بفاء عطف ما ليس صله ... على الذي استقر أنه الصلة\nبعضا بحتى اعطف على كل ولا ... يكون إلا غاية الذي تلا\nوأم بها اعطف إثر همز التسوية ... أو همزة عن لفظ أي مغنيه\nوربما أسقطت الهمزة إن ... كان خفا المعنى بحذفها أمن\nوبانقطاع وبمعنى بل وفت ... إن تك مما قيدت به خلت\nخير أبح قسم وأبهم ... واشكك وإضراب بها أيضا نمي\nوربما عاقبت الواو إذا ... لم يلف ذو النطق للبس منفذا\nومثل أو القصد إما الثانية ... في نحو إما ذي وإما النائية\nوأول لكن نفيا أو نهيا ولا ... نداء او أمرا أو اثباتا تلا\nوبل كلكن بعد مصحوبيها ... كلم أكن في مربع بل تيها\nوانقل بها للثان حكم الأول ... في الخبر المثبت والأمر الجلي\nوإن على ضمير رفع متصل ... عطفت فافصل بالضمير المنفصل\nأو فاصل ما ولا فصل يرد ... في النظم فاشيا وضعفه اعتقد\nوعود خافض لدى عطف على ... ضمير خفض لازما قد جعلا\nوليس عندي لازما إذ قد أتى ... في النظم والنثر الصحيح مثبتا\nوالفاء قد تحذف مع ما عطفت ... والواو إذ لا لبس وهي انفردت\nبعطف عامل مزال قد بقي ... معموله دفعا لوهم اتقي\nوحذف متبوع بدا عنا استبح ... وعطفك الفعل على الفعل يصح\nواعطف على اسم شبه فعل فعلا ... وعكسا استعمل تجده سهلا"},{"id":"alfiyya:44","bookId":"alfiyya","type":"section","seq":44,"chapter":"مقدمة المؤلف","title":"البدل","page":"ج1 ص48","text":"التابع المقصود بالحكم بلا ... واسطة هو المسمى بدلا\nمطابقا أو بعضا او ما يشتمل ... عليه يلفى أو كمعطوف ببل\nوذا للاضراب اعز إن قصدا صحب ... ودون قصد غلط به سلب\nكزره خالدا وقبله اليدا ... واعرفه حقه وخدنبلا مدى\nومن ضمير الحاضر الظاهر لا ... تبدله إلا ما إحاطة جلا\nأو اقتضى بعضا او اشتمالا ... كأنك ابتهاجك استمالا\nوبدل المضمن الهمز يلي ... همزا كمن ذا أسعيد أم علي\nويبدل الفعل من الفعل كمن ... يصل إلينا يستعن بما يعن"},{"id":"alfiyya:45","bookId":"alfiyya","type":"section","seq":45,"chapter":"مقدمة المؤلف","title":"النداء","page":"ج1 ص49","text":"وللمنادى الناء أو كالناء يا ... وأي وآكذا أيا ثم هيا\nوالهمز للداني ووا لمن ندب ... أو يا وغير وا لدى اللبس اجتنب\nوغير مندوب ومضمر وما ... جامستغاثا قد يعرى فاعلما\nوذاك في اسم الجنس والمشارله ... قل ومن يمنعه فانصر عاذله\nوابن المعرف المنادى المفردا ... عهداعلى الذي في رفعه قد\nوانو انضمام ما بنوا قبل الندا ... وليجرى مجرى ذي بناء جددا\nوالمفرد المنكور والمضافا ... وشبهه انصب عادما خلافا\nونحو زيد ضم وافتحن من ... نحو أزيد بن سعيد لا تهن\nوالضم إن لم يل الابن علما ... أو يل الابن علم قد حتما\nواضمم أو انصب ما اضطرارا نونا ... مما له استحقاق ضم بينا\nوباضطرار خص جمع يا وأل ... إلا مع الله ومحكي الجمل\nوالأكثر اللهم بالتعويض ... وشذ يا اللهم في قريض"},{"id":"alfiyya:46","bookId":"alfiyya","type":"section","seq":46,"chapter":"مقدمة المؤلف","title":"فصل","page":"ج1 ص50","text":"تابع ذي الضم المضاف دون أل ... ألزمه نصبا كأزيد ذا الحيل\nوما سواه ارفع أو انصب واجعلا ... كمستقل نسقا وبدلا\nوإن يكن مصحوب أل ما نسقا ... ففيه وجهان ورفع ينتقى\nوأيها مصحوب ال بعد صفه ... يلزم بالرفع لدى ذي المعرفة\nرأي هذا أيها الذي ورد ... ووصف أي بسوى هذا يرد\nوذو إشارة كأي في الصفه ... إن كان تركها يفيت المعرفه\nفي نحو سعد سعد الأوس ينتصب ... ثان وضم وافتح اولا تصب"},{"id":"alfiyya:47","bookId":"alfiyya","type":"section","seq":47,"chapter":"مقدمة المؤلف","title":"المنادى المضاف الى ياء المتكلم","page":"ج1 ص50","text":"واجعل منادى صح إن يضف ليا\n... كعبد عبدي عبد عبدا عبديا\nوفتح او كسر وحذف اليا استمر\n... في يا ابن أم يا ابن عم لا مفر\nوفي الندا \" أبت\" \" أمت\" عرض\n... واكسر أوافتح ومن اليا التا عوض"},{"id":"alfiyya:48","bookId":"alfiyya","type":"section","seq":48,"chapter":"مقدمة المؤلف","title":"أسماء لازمت النداء","page":"ج1 ص51","text":"\"وفل\" بعض ما يخص بالندا ... لؤمان نومان كذا واطردا\nفي سب الانثى وزن يا خباث ... والأمر هكذا من الثلاثي\nوشاع في سب الذكور فعل\n... ولا تقس وجر في الشعر فل"},{"id":"alfiyya:49","bookId":"alfiyya","type":"section","seq":49,"chapter":"مقدمة المؤلف","title":"الاستغاثة","page":"ج1 ص51","text":"إذا استغيث اسم منادى خفضا ... باللام مفتوحا كيا للمرتضى\nوافتح مع المعطوف إن كررت يا ... وفي سوى ذلك بالكسر ائتيا\nولام ما استغيث عاقبت ألف ... ومثله اسم ذو تعجب ألف"},{"id":"alfiyya:50","bookId":"alfiyya","type":"section","seq":50,"chapter":"مقدمة المؤلف","title":"الندبة","page":"ج1 ص51","text":"ما للمنادى اجعل لمندوب وما ... نكر لم يندب ولا ما أبهما\nويندب الموصول بالذي اشتهر ... كبئر زمزم يلي وا من حفر\nومنتهى المندوب صله بالألف ... متلوها إن كان مثلها حذف\nكذاك تنوين الذي به كمل ... من صلة أو غيرها نلت الأمل\nوالشكل حتما أوله مجانسا ... إن يكن الفتح بوهم لابسا\nوواقفا زد هاء سكت إن ترد ... وإن تشأ فالمد والها لا تزد\nوقائل واعبديا واعبدا ... من في الندا اليا ذا سكون أبدى"},{"id":"alfiyya:51","bookId":"alfiyya","type":"section","seq":51,"chapter":"مقدمة المؤلف","title":"الترخيم","page":"ج1 ص52","text":"ترخيما احذف اخر المنادى ... كيا سعا فيمن دعا سعادا\nوجوزنه مطلقا في كل ما ... أنث بالها وبالذي قد رخما\nبحذفها وفره بعد واحظلا ... ترخيم ما من هذه الها قد خلا\nإلا الرباعي فما فوق العلم ... دون إضافة وإسناد متم\nومع الآخر احذف الذي تلا ... إن ريد لينا ساكنا مكملا\nأربعة فصاعدا والخلف في ... واو وياء بهما فتح قفي\nوالعجز احذف من مركب وقل ... ترخيم حملة وذا عمرو نقل\nوإن نويت بعد حذف ما حذف ... فالباقي استعمل بما فيه ألف\nواجعله إن لم تنو محذوفا كما ... لو كان بالآخر وضعا تمما\nفقل على الأول في ثمود يا ... ثمو ويا ثمي على الثاني بيا\nوالتزم الأول في كمسمله ... وجوز الوجهين في كمسلمه\nولاضطرار رخموا دون ندا ... ما للندا يصلح نحو أحمد\nلاختصاص:"},{"id":"alfiyya:52","bookId":"alfiyya","type":"section","seq":52,"chapter":"مقدمة المؤلف","title":"الاختصاص","page":"ج1 ص53","text":"كنداء دون يا\n... كأيها الفتى بإثر ارجونيا\nوقد يرى ذا دون أي تلو أل\n... كمثل نحن العرب أسخى من بذل"},{"id":"alfiyya:53","bookId":"alfiyya","type":"section","seq":53,"chapter":"مقدمة المؤلف","title":"التحذير والأغراء","page":"ج1 ص53","text":"إياك والشر ونحوه نصب ... محذر بما استتاره وجب\nودون عطف ذا لأيا انسب وما ... سواه ستر فعله لن يلزما\nإلا مع العطف أو التكرار ... كالضيغم الضيم يا ذا الساري\nوشذ إياي وإياه أشذ ... وعن سبيل القصد من قاس انتبذ\nوكمحدر بلا إيا اجعلا ... مغزى به كل ما قد فصلا"},{"id":"alfiyya:54","bookId":"alfiyya","type":"section","seq":54,"chapter":"مقدمة المؤلف","title":"أسماء الأفعال والأصوات","page":"ج1 ص53","text":"ما ناب عن فعل كشتان وصه ... هو اسم فعل وكذا أوه ومه\nوما بمعنى افعل كآمين كثر ... وغيره كوي وهيهات نزر\nوالفعل من أسمائه عليكما ... وهكذا دونك مع إليكما\nكذا رويد بله ناصبين ... ويعملان الخفض مصدرين\nوما لما تنوب عنه عن عمل ... لها وأخر مالذي فيه العمل\nواحكم بتنكير الذي ينون ... منها وتعربف سواه بين\nوما به خوطب ما لا يعقل ... من مشبه اسم الفعل صوتا يجعل\nكذا الذي أجدى حكاية كقب ... والزم بنا النوعين فهو قد وجب"},{"id":"alfiyya:55","bookId":"alfiyya","type":"section","seq":55,"chapter":"مقدمة المؤلف","title":"نونا التوكيد","page":"ج1 ص54","text":"للفعل توكيد بنونين هما ... كنوني اذهبن واقصدنهما\nيؤكدان افعل ويفعل آتيا ... ذا طلب أو شرطا أما تاليا\nأو مثبتا في قسم مستقبلا ... وقل بعد ما ولم وبعد لا\nوغير إما من طوالب الجزا ... وآخر المؤكد افتح كابرزا\nواشكله قبل مضمر لين بما ... جانس من تحرك قد علما\nوالمضمر احذفنه إلا الألف ... وإن يكن في آخر الفعل ألف\nفاجعله منه رافعا غير اليا ... والواو ياء كاسعين سعيا\nواحذفه من رافع هاتين وفي ... وا ويا شكل مجانس قفي\nنحو اخشين يا هند بالكسر ويا ... قوم اخشون واضمم وقس مسويا\nولم تقع خفيفة بعد الألف ... لكن شديدة وكسرها ألف\nوألفا زد قبلها مؤكدا ... فعلا الى نون الإناث أسندا\nواحذف خفيفة لساكن ردف ... وبعد غير فتحة إذا تقف\nواردد إذا حذفتها في الوقف ما ... من أجلها في الوصل كان عدما\nوأبدلنها بعد فتح ألفا ... وقفا كما تقول في قفن قفا"},{"id":"alfiyya:56","bookId":"alfiyya","type":"section","seq":56,"chapter":"مقدمة المؤلف","title":"ما لا ينصرف","page":"ج1 ص55","text":"الصرف تنوين أتى مبينا ... معنى به يكون الاسم أمكنا\nفألف التأنيث مطلقا منع ... صرف الذي حواه كيفما وقع\nوزائدا فعلان في وصف سلم ... من أن يرى بتاء تأنيث ختم\nووصف أصلي ووزن أفعلا ... ممنوع تأنيث بتا كأشهلا\nوألغين عارض الوصفيه ... كأربع وعارض الإسميه\nفالأدهم القيد لكونه وضع ... في الأصل وصفا انصرافه منع\nوأجدل وأخيل وأنعى ... مصروفة وقد ينلن المنعا\nومنع عدل مع وصف معتبر ... في لفظ مثنى وثلاث وأخر\nووزن مثنى وثلاث كهما ... من واحد لأربع فليعلما\nوكن لجمع مشبه مفاعلا ... أو المفاعيل بمنع كافلا\nوذا اعتلال منه كالحواري ... رفعا وجرا أجره كساري\nولسراويل بهذا الجمع ... شبه اقتضى عموم المنع\nوإن به سمي أو بما لحق ... به فالانصراف منعه يحق\nوالعلم امنع صرفه مركبا ... تركيب مزج نحو معديكربا\nكذاك حاوي زائدي فعلانا ... كغطفان وكأصبهانا\nكذا مؤنث بهاء مطلقا ... وشرط منع العار كونه ارتقى\nفوق الثلاث أو كجور أو سقر ... أو زيد اسم امرأة لا اسم ذكر\nوجهان في العادم تذكيرا سبق ... وعجمة كهند والمنع أحق\nوالعجمي الوضع والتعريف مع ... زيد على الثلاث صرفه امتنع\nكذاك ذو وزن يخص الفعلا ... أو غالب كأحمد ويعلى\nوما يصير علما من ذي ألف ... زيدت لإلحاق فليس ينصرف\nوالعلم امنع صرفه إن عدلا ... كفعل التوكيد أو كثعلا\nوالعدل والتعريف مانعا سحر ... إذا به التعيين قصدا يعتبر\nابن على الكسر فعال علما ... مؤنثا وهو نظير جشما\nعند تميم واصرفن ما نكرا ... من كل ما التعريف فيه أثرا\nوما يكون منه منقوصا ففي ... إعرابه نهج جوار يقتفي\nولاضطرار أو تناسب صرف ... ذو المنع والمصروف قد لا ينصرف"},{"id":"alfiyya:57","bookId":"alfiyya","type":"section","seq":57,"chapter":"مقدمة المؤلف","title":"إعراب الفعل","page":"ج1 ص57","text":"رفع مضارعا إذا يجرد ... من ناصب وجازم كتسعد\nوبلن انصبه وكي كذا بأن ... لا بعد علم والتي من بعد ظن\nفانصب بها والرفع صحح واعتقد ... تخفيفها من أن فهو مطرد\nوبعضهم أهمل أن حملا على ... ما أختها حيث استحقت عملا\nونصبوا بإذن المستقبلا ... إن صدرت والفعل بعد موصلا\nأو قبله اليمين وانصب وارفعا ... إذا إذن من بعد عطف وقعا\nوبين لا ولام جر إلتزم ... إظهار أن ناصبة وإن عدم\nلا فأن اعمل مظهرا أو مضمرا ... وبعد نفي كان حتما أضمرا\nكذاك بعد أو إذا يصلح في ... موضعها حتى أو والا أن خفي\nوبعد حتى هكذا إضمار أن ... حتم كجد حتى تسرد ذا حزن\nوتلو حتى حالا أو مؤولا ... به ارفعن وانصب المستقبلا\nوبعد فا جواب نفي أو طلب ... محضين أن وسترها حتم نصب\nوالواو كالفا إن تفد مفهوم مع ... كلا تكن جلدا وتظهر الجزع\nوبعد غير النفي جزما اعتمد ... إن تسقط الفا والجزاء قد قصد\nوشرط جزم بعد نهي أن تضع ... إن قبل لا دون تخالف يقع\nوالأمر إن كان بغير افعل فلا ... تنصب جوابه وجزمه اقبلا\nوالفعل بعد الفاء في الرجا نصب ... كنصب ما الى التمنى ينتسب\nوإن على اسم خالص فعل عطف ... تنصبه أن ثابتا أو منحذف\nوشذ حذف أن ونصب في سوى ... ما مر فاقبل منه عدل روى"},{"id":"alfiyya:58","bookId":"alfiyya","type":"section","seq":58,"chapter":"مقدمة المؤلف","title":"عوامل الجزم","page":"ج1 ص58","text":"بلا ولام طالبا ضع جزما ... في الفعل هكذا بلم ولما\nواجزم بإن ومن وما ومهما ... أي متى أيان أين إذ ما\nوحيثما أتى وحرف إذ ما ... كإن وباقي الأدوات أسما\nفعلين يقتضين شرط قدما ... يتلو الجزاء وجوابا وسما\nوماضيين أو مضارعين ... تلفيهما أو متخالفين\nوبعد ماض رفعك الجزا حسن ... ورفعه بعد مضارع وهن\nواقرن بفا حتما جوابا لو جعل ... شرطا لإن أو غيرها لم ينجعل\nوتخلف الفاء إذا المفاجأة ... كإن تجد إذا لنا مكافأة\nوالفعل من بعد الجزا إن يقترن ... بالفا أو الواو بتثليث قمن\nوجزم او نصب لفعل إثر فا ... أو واو ان بالجملتين اكتنفا\nوالشرط يغني عن جواب قد علم ... والعكس قد يأتي إن المعنى فهم\nواحذف لدى اجتماع شرط وقسم ... جواب ما أخرت فهو ملتزم\nوإن تواليا وقبل ذو خبر ... فالشرط رجح مطلقا بلا حذر\nوربما رجح بعد قسم ... شرط بلا ذي خبر مقدم"},{"id":"alfiyya:59","bookId":"alfiyya","type":"section","seq":59,"chapter":"مقدمة المؤلف","title":"فصل لو","page":"ج1 ص59","text":"لو حرف شرط في مضي ويقل ... إيلاؤه مستقبلا لكن قبل\nوهي في الاختصاص بالفعل كإن ... لكن لو أن بها قد تقترن\nوإن مضارع تلاها صرفا ... الى المضي نحو لو يفي كفى"},{"id":"alfiyya:60","bookId":"alfiyya","type":"section","seq":60,"chapter":"مقدمة المؤلف","title":"أما ولولا ولوما","page":"ج1 ص59","text":"أما كمهما يك من شيء وفا ... لتلو تلوها وجوبا ألفا\nوحذف ذي الفا قل في نثر إذا ... لم يك قول معها قد نبذا\nلولا ولوما يلزمان الابتدا ... إذا امتناعا بوجود عقدا\nوبهما التحضيض مز وهلا ... ألا ألا وأولينها الفعلا\nوقد يليها اسم بفعل مضمر ... علق أو بظاهر مؤخر"},{"id":"alfiyya:61","bookId":"alfiyya","type":"section","seq":61,"chapter":"مقدمة المؤلف","title":"الإخبار بالذي والألف واللام","page":"ج1 ص60","text":"ما قيل أخبر عنه بالذي خبر ... عن الذي مبتدأ قبل استقر\nوما سواهما فوسطه صله ... عائدها خلف معطي التكملة\nنحو الذي ضربته زيد فذا ... ضربت زيدا كان فادر المأخذا\nوباللذين واللذين والتي ... أخبر مراعيا وفاق المثبت\nقبول تأخير وتعريف لما ... أخبر عنه هاهنا قد حتما\nكذا الغني عنه بأجنبي أو ... بمضمر شرط فراع ما رعوا\nوأخبروا هنا بأل عن بعض ما ... يكون فيه الفعل قد تقدما\nإن صح صوغ صلة منه لأل ... كصوغ واق من وقى الله البطل\nوإن يكن ما رفعت صلة أل ... نمير غيرها أبين وانفصل\nومائة والألف للفرد أضف ... ومائة بالجمع نزرا قد ردف\nوأحد ذكر وصلنه بعشر ... مركبا قاصد معدود ذكر\nوقل لدى التأنيث إحدى عشره ... والشين فيها عن تميم كسره\nومع غير أحد وإحدى ... ما معهما فعلت فافعل قصدا\nولثلاثة وتسعة وما ... بينهما إن ركبا ما قدما\nوأول عشرة اثنتي وعشرا ... إثني إذا أثنى تشا أو ذكرا\nواليا لغير الرفع وارفع بالألف ... والفتح في جزأي سواهما ألف\nوميز العشرين للتسعينا ... بواحد كأربعين حينا\nوميزوا مركبا بمثل ما ... ميز عشرون فسوينهما\nوإن أضيف عدد مركب ... يبق البنا وعجز قد يعرب\nوصغ من اثنين فما فوق إلى ... عشرة كفاعل من فعلا\nواختمه في التأنيث بالتا ومتى ... ذكرت فاذكر فاعلا بغير تا\nوإن ترد بعض الذي منه بني ... تضف إليه مثل بعض بين\nوإن ترد جعل الأقل مثل ما ... فوق فحكم جاعل له احكما\nوإن أردت مثل ثاني اثنين ... مركبا فجئ بتركيبين\nأو فاعلا بحالتيه أضف ... الى مركب بما تنوي يفي\nوشاع الاستعنا بحادي عشرا ... ونحوه وقبل عشرين اذكرا\nوبابه الفاعل من لفظ العدد ... بحالتيه قبل واو يعتمد"},{"id":"alfiyya:62","bookId":"alfiyya","type":"section","seq":62,"chapter":"مقدمة المؤلف","title":"العدد","page":"ج1 ص62","text":"ثلاثة بالتاء قل للعشره ... في عد ما احاده مذكره\nفي الضد جرد والمميز اجرر ... جمعا بلفظ قلة في الأكثر"},{"id":"alfiyya:63","bookId":"alfiyya","type":"section","seq":63,"chapter":"مقدمة المؤلف","title":"كم وكأي وكذا","page":"ج1 ص60","text":"...\nكم وكأين وكذا:\nميز في الاستفهام كم بمثل ما ... ميزت عشرين ككم شخصا سما\nوأجز أن تجره من مضمرا ... إن وليت كم حرف جر مظهرا\nواستعملنها مخبرا كعشره ... أو مائة ككم رجال أو مره\nككم كأين وكذا وينتصب ... تمييز ذين أو به صل من تصب"},{"id":"alfiyya:64","bookId":"alfiyya","type":"section","seq":64,"chapter":"مقدمة المؤلف","title":"الحكاية","page":"ج1 ص62","text":"احك بأي ما لمنكور سئل ... عنه بها في الوقف أو حين تصل\nووقفا احك ما لمنكور بمن ... والنون حرك مطلقا وأشبعن\nوقل منان ومنين بعد لي ... إلفان بابنين وسكن تعدل\nوقل لمن قال أتت بنت منه ... والنون قبل تا المثنى مسكنه\nوالفتح نزر وصل التا والألف ... بمن بإثر ذا بنسوة كل\nوقل منون ومنين مسكنا ... إن قيل جا قوم لقوم فطنا\nوإن تصل فلفظ من لا يختلف ... ونادر منون في نظم عرف\nوالعلم احكينه من بعد من ... إن عريت من عاطف بها اقترن"},{"id":"alfiyya:65","bookId":"alfiyya","type":"section","seq":65,"chapter":"مقدمة المؤلف","title":"التأنيث","page":"ج1 ص63","text":"علامة التأنيث تاء أو ألف ... وفي أسام قدروا التاء كالكتف\nويعرف التقدير بالضمير ... ونحوه كالرد في الصغير\nولا تلي فارقة فعولا ... أصلا ولا المفعال والمفعيلا\nكذاك مفعل وما تليه تا ... الفرق من ذي فشذود فيه\nومن فعيل كقتيل إن تبع ... موصوفه غالبا التا تمتنع\nوألف التأنيث ذات قصر ... وذات مد نحو أنثى الغر\nوالإشتهار في مباني الأولى ... يبديه وزن أربى والطولى\nومرطى ووزن فعلى جمعا ... أو مصدرا أو صفة كشبعى\nوكحبارى سمهى سبطري ... ذكرى وحثيثى مع الكفرى\nكذاك خليطى مع الشقارى ... واعز لغير هذه استندارا\nلمدها فعلاء أفعلاء ... مثلث العين وفعللاء\nثم فعلا فعللا فاعولا ... وفاعلاء فعليا مفعولا\nومطلق العين فعالا وكذا ... مطلق فاء فعلاء أخذا"},{"id":"alfiyya:66","bookId":"alfiyya","type":"section","seq":66,"chapter":"مقدمة المؤلف","title":"المقصور والممدود","page":"ج1 ص63","text":"إذا اسم استوجب من قبل الطرف ... فتحا وكان ذا نظير كالأسف\nفلنظيره المعل الآخر ... ثبوت قصر بقياس ظاهر\nكفعل وفعل في جمع ما ... كفعلة وفعلة نحو الدمى\nوما استحق قبل آخر ألف ... فالمد في نظيره حتما عرف\nكمصدر الفعل الذي قد بدئا ... بهمز وصل كارعوى وكارتأى\nوالعادم النظير ذا قصر وذا ... مد بنقل كالحجا وكالحذا\nوقصر ذي المد اضطرارا مجمع ... عليه والعكس بحلف يقع"},{"id":"alfiyya:67","bookId":"alfiyya","type":"section","seq":67,"chapter":"مقدمة المؤلف","title":"كيفية تثنية المقصور والممدود وجمعهما تصحيحا","page":"ج1 ص64","text":"آخر مقصور تثنى اجعله يا ... إن كان عن ثلاثة مرتقيا\nكذا الذي اليا أصله نحو الفتى ... والجامد الذي أميل كمتى\nفي غير ذا تقلب واوا الألف ... وأولها ما كان قبل قد ألف\nوما كصحراء بواو ثنيا ... ونحو علباء كساء وحيا\nبواو او همز وغير ما ذكر ... صحح وما شذ على نقل قصر\nواحذف من المقصور في جمع على ... حد المثنى ما به تكملا\nوالفتح أبق مشعرا بما حذف ... وإن جمعته بتاء وألف\nفالألف اقلب قلبها في التثنيه ... وتاء ذي التا ألزمن تنحيه\nوالسالم العين الثلاثي اسما أنل ... إتباع عين فاءه بما شكل\nإن ساكن العين مؤنثا بدا ... مختتما بالتاء أو مجردا\nوسكن التالي غير الفتح أو ... خففه بالفتح فكلا قد رووا\nومنعوا إتباع نحو ذروه ... وزبية وشذ كسر جروه\nونادر أو ذو اضطرار غير ما ... قدمته أو لأناس انتمى"},{"id":"alfiyya:68","bookId":"alfiyya","type":"section","seq":68,"chapter":"مقدمة المؤلف","title":"جمع التكسير","page":"ج1 ص65","text":"أفعلة أفعل ثم فعله ... تمت أفعال جموع قلة\nوبعض ذي بكثرة وضعا يفي ... كأرجل والعكس جاء كالصفي\nلفعل اسما صح عينا أفعل ... وللرباعي اسما أيضا يجعل\nإن كان كالعناق والذراع في ... مد وتأنيث وعد الأحرف\nوغير ما أفعل فيه مطرد ... من الثلاثي اسما بأفعال يرد\nوغالبا أغناهم فعلان ... في فعل كقولهم صردان\nفي اسم مذكر رباعي بمد ... ثالث افعلة عنهم اطرد\nوالزمه في فعال أو فعال ... مصاحبي تضعيف أو اعلال\nفعل لنحو أحمر وحمرا ... وفعلة جمعا بنقل يدرى\nوفعل لاسم رباعي بمد ... قد زيد قبل لام اعلالا فقد\nما لم يضاعف في الأعم ذو الألف ... وفعل جمعا لفعلة عرف\nونحو كبرى ولفعلة فعل ... وقد يجئ جمعه على فعل\nفي نحو رام اطراد فعله ... وشاع نحو كامل وكمله\nفعلى لوصف كقتيل وزمن ... وهالك وميت به قمن\nلفعل اسما صح لاما فعله ... والوضع في فعل وفعل قلله\nوفعل لفاعل وفاعله ... وصفين نحو عاذل وعاذله\nومثله الفعال فيما ذكرا ... وذان في المعل لاما تدرا\nفعل وفعلة فعال لهما ... وقل فيما عينه اليا منهما\nوفعل أيضا له فعال ... ما لم يكن في لامه اعتلال\nأو يك مضعفا ومثل فعل ... ذو التا وفعل مع فعل فاقبل\nوفي فعيل وصف فاعل ورد ... كذاك في أنثاه أيضا اطرد\nوشاع في وصف على فعلانا ... أو انثييه أو على فعلانا\nومثله فعلانة والزمه في ... نحو طويل وطويلة تفي\nوبفعول فعل نحو كبد ... يخص غالبا كذاك يطرد\nفي فعل اسما مطلق الفا وفعل ... له وللفعال فعلان حصل\nوشاع في حوت وقاع مع ما ... ضاهاهما وقل في غيرهما\nوفعلا اسما وفعيلا وفعل ... غير معل العين فعلان شمل\nولكريم وبخيل فعلا ... كذا لما ضاهاهما قد جعلا\nوناب عنه أفعلاء في المعل ... لاما ومضعف وغير ذاك قل\nفواعل لفوعل وفاعل ... وفاعلاء مع نحو كاهل\nوحائض وصاهل وفاعله ... وشذ في الفارس مع ما ماثله\nوبفعائل اجمعن فعاله ... وشبهه ذا تاء أو مزاله\nوبالفعالي والفعالى جمعا ... صحراء والعذراء والقيس اتبعا\nواجعل فعالي لغير ذي نسب ... جدد كالكرسي تتبع العرب\nوبفعالل وشبهه انطقا ... في جمع ما فوق الثلاثة ارتقى\nمن غير ما مضى ومن خماسي ... جرد الآخر انف بالقياس\nوالرابع الشبيه بالمزيد قد ... يحذف دون ما به تم العدد\nوزائد العادي الرباعي احذفه ... ما لم يك لينا إثره اللذ ختما\nوالسين والتا من كمستدع أزل ... إذ ببنا الجمع بقاهما مخل\nوالميم أولى من سواه بالبقا ... والهمز والياء مثله إن سبقا\nوالياء لا الواو احذف ان جمعت ما ... كحيز بون فهو حكم حتما\nوخيروا في زائدي سرندى ... وكل ما ضاهاه كالعلندى"},{"id":"alfiyya:69","bookId":"alfiyya","type":"section","seq":69,"chapter":"مقدمة المؤلف","title":"التصغير","page":"ج1 ص68","text":"فعيلا اجعل الثلاثي إذا ... صغرته نحو قذي في قذا\nفعيعل مع فعيعيل لما ... فاق كجعل درهم دريهما\nوما به لمنتهى الجمع وصل ... به إلى أمثلة التصغير صل\nوجائز تعويض يا قبل الطرف ... إن كان بعض الاسم فيهما انحذف\nوحائد عن القياس كل ما ... خالف في البابين حكما رسما\nلتلو يا التصغير من قبل علم ... تأنيث أو مدته الفتح انحتم\nكذاك ما مدة أفعال سبق ... أو مد سكران وما به التحق\nوألف التأنيث حيث مدا ... وتاؤه منفصلين عدا\nكذا المزيد آخرا للنسب ... وعجز المضاف والمركب\nوهكذا زيادتنا فعلانا ... من بعد أربع كزعفرانا\nوقدر انفصال ما دل على ... تثنية أو جمع تصحيح جلا\nوألف التأنيث ذو القصر متى ... زاد على أربعة لن يثبتا\nوعند تصغير حبارى خير ... بين الحبيرى فاد والحبير\nواردد لأصل ثانيا لينا قلب ... فقيمة صير قويمة تصب\nوشذ في عيد عييد وحتم ... للجمع من ذا ما لتصغير علم\nوالألف الثان المزيد يجعل ... واوا كذا ما الأصل فيه يجهل\nوكمل المنقوص في التصغير ما ... لم يحو غير التاء ثالثا كما\nومن بترخيم يصغر اكتفى ... بالأصل كالعطيف يعني المعطفا\nاختم بتا التأنيث ما صغرت ... من مؤنث غار ثلاثي كسن\nما لم يكن بالتا يرى ذا لبس ... كشجر وبقر وخمس\nوشذ ترك دون لبس وندر ... لحاق تا فيما ثلاثيا كثر\nوصغروا شذوذا الذي التي ... وذا مع الفروع منها تا وتي"},{"id":"alfiyya:70","bookId":"alfiyya","type":"section","seq":70,"chapter":"مقدمة المؤلف","title":"النسب","page":"ج1 ص69","text":"ياء كيا الكرسي زادوا للنسب ... وكل ما تليه كسره وجب\nومثله مما حواه احذف وتا ... تأنيث أو مدته لا تثبتا\nوإن تكن تربع ذا ثان سكن ... فقلبها واوا وحذفها حسن\nلشبهها الملحق والأصلي ما ... لها وللأصلي قلب يعتمى\nوالألف الجائز أربعا أزل ... كذاك يا المنقوص خامسا عزل\nوالحذف في اليا رابعا أحق من ... قلب وحتم قلب ثالث يعن\nوأول ذا القلب انفتاحا وفعل ... وفعل عينهما افتح وفعل\nوقيل في المرمي مرموي ... واختير في استعمالهم مرمي\nونحو حي فتح ثانيه يجب ... واردده واوا إن يكن عنه قلب\nوعلم التثنية احذف للنسب ... ومثل ذا في جمع تصحيح وجب\nوثالث من نحو طيب حذف ... وشذ طائي مقولا بالألف\nوفعلي في فعيلة التزم ... وفعلي في فعيلة حتم\nوألحقوا معل لام عريا ... من المثالين بما التا أوليا\nوتمموا ما كان كالطويله ... وهكذا ما كان كالجليله\nوهمز ذي مد ينال في النسب ... ما كان في تثنية له انتسب\nوانسب لصدر جملة وصدر ... ما ركب مزجا ولثان تمما\nإضافة مبدوءة بابن أو اب ... أو ماله التعريف بالثاني وجب\nفيما سوى هذا انسبن للأول ... ما لم يخف لبس كعبد الأشهل\nواجبر برد اللام ما منه حذف ... جوازا ان لم يك رد ألف\nفي جمعي التصحيح أو في التثنيه ... وحق مجبور بهاذي بتوفيه\nوبأخ أختا وبابن بنتا ... ألحق ويونس أبى حذف التا\nوضاعف الثاني من ثنائي ... ثانيه ذولين كلا ولائي\nوإن يكن كشية ما الفا عدم ... فجبره وفتح عينيه التزم\nوالواحد اذكر ناسبا للجمع ... إن لم يشابه واحدا بالوضع\nومع فاعل وفعال فعل ... في نسب أغنى عن اليا فقبل\nوغير ما أسلفته مقررا ... على الذي ينقل منه اقتصرا"},{"id":"alfiyya:71","bookId":"alfiyya","type":"section","seq":71,"chapter":"مقدمة المؤلف","title":"الوقف","page":"ج1 ص71","text":"تنوينا اثر فتح اجعل ألفا ... وقفا وتلو غير فتح احذفا\nواحذف لوقف في سوى اضطرار ... صلة غير الفتح في الإضمار\nوأشبهت إذا منونا نصب ... فألفا في الوقف نونها قلب\nوحذف يا المنقوص ذي التنوين ... ما لم ينصب اولى من ثبون فاعلما\nوغير ذي التنوين بالعكس وفي ... نحو مر لزوم رد اليا اقتفي\nوغيرها التأنيث من محرك ... سكنه أو قف رائم التحرك\nأو أشمم الضمة أو قف مضعفا ... ما ليس همزا أو عليلا إن قفا\nمحركا وحركات انقلا ... لساكن تحريكه لن يحظلا\nونقل فتح من سوى المهموزلا ... يراه بصري وكوف نقلا\nوالنقل إن يعدم نظير ممتنع ... وذاك في المهموز ليس يمتنع\nفي الوقف تا تأنيث الاسم ها جعل ... إن لم يكن بساكن صح وصل\nوقل ذا في جمع تصحيح وما ... ضاهى وغير ذين بالعكس انتمى\nوقف بها السكت على الفعل المعل ... بحذف آخر كأعط من سأل\nوليس حتما في سوى ماكع أو ... كيع مجزوما فراع ما رعوا\nوما في الاستفهام إن جرت حذف ... ألفها وأولها الها إن تقف\nوليس حتما في سوى ما انخفضا ... باسم كقولك اقتضاء م اقتضى\nووصل ذي الهاء أجز بكل ما ... حرك تحريك بناء لزما\nووصلها بغير تحريك بنا ... أديم شذ في المدام استحسنا\nلربما أعطى لفظ الوصل ما ... للوقوف نثرا وفشا منتظما"},{"id":"alfiyya:72","bookId":"alfiyya","type":"section","seq":72,"chapter":"مقدمة المؤلف","title":"الإمالة","page":"ج1 ص72","text":"الألف المبدل من يا في طرف ... أمل كذا الواقع منه اليا خلف\nدون مزيد أو شذوذ ولما ... تليه ها التأنيث ما الها عدما\nوهكذا بدل عين الفعل إن ... يؤل الى فلت كماضي خف ودن\nكذاك تالي الياء والفصل اغتفر ... بحرف أو مع هاكجيبها أدر\nكذاك ما يليه كسر أو يلي ... تالي كسر أو سكون قد ولي\nكسرا وفصل الها كلا فصل يعد ... فدرهماك من يمله لم يصد\nوحرف الاستعلا يكف مظهرا ... من كسر أو يا وكذا تكف زا\nإن كان ما يكف بعد متصل ... أو بعد حرف أو بحرفين فصل\nكذا إذا قدم ما لم ينكسر ... أو يسكن إثر الكسر كالمطواع مر\nوكف مستعل ورا ينكف ... بكسر را كغارما لا أجفو\nولا تمل لسبب ما لم يتصل ... والكف قد يوجبه ما ينفصل\nوقد أمالوا لتناسب بلا ... داع سواها كعمادا وتلا\nولا تمل ما لم ينل تمكنا ... دون سماع غيرها وغيرنا\nوالفتح قبل كسر راء في طرف ... امل كللأيسر مل تكف الكلف\nكذا الذي تليه ها التأنيث في ... وقف إذا ما كان غير ألف"},{"id":"alfiyya:73","bookId":"alfiyya","type":"section","seq":73,"chapter":"مقدمة المؤلف","title":"التصريف","page":"ج1 ص73","text":"حرف وشبهه من الصرف بري ... وما سواهما بتصريف حري\nوليس أدنى من ثلاثي يرى ... قابل تصريف سوى ما غيرا\nومنتهى اسم خمس أن تجردا ... وإن يزد فيه فما سبعا عدا\nوغير اخر الثلاثي افتح وضم ... واكسر وزد تسكين ثانيه تعم\nوفعل أهمل والعكس يقل ... لقصدهم تخصيص فعل بفعل\nوافتح وضم واكسر الثاني من ... فعل ثلاثي وزد نحو ضمن\nومنتهاه أربع إن جردا ... وإن يزد فيه فما ستا عدا\nلاسم مجرد رباع فعلل ... وفعلل وفعلل وفعلل\nومع فعل فعلل وإن ... علا فمع فعلل حوى فعللا\nكذا فعلل وفعلل وما ... غاير للزبد أو النقص انتمى\nوالحرف إن يلزم فأصل والذي ... لا يلزم الزائد مثل تا احتذى\nبضمن فعل قابل الأصول في ... وزن وزائد بلفظه اكتفي\nوضاعف اللام إذا أصل بقى ... كراء جعفر وقاف فستق\nوإن يك الزائد ضعف أصل ... فاجعل في الوزن ما للأصل\nواحكم بتأصيل حروف سمسم ... ونحوه والخلف في كلملم\nفبألف أكثر من أصلين ... صاحب زائد بغير مين\nواليا كذا والواو إن لم يقعا ... كما هما في يؤيؤ وعوعا\nوهكذا همز وميم سبقا ... ثلاثة تأصيلها تحققا\nكذاك همز اخر بعد ألف ... أكثر من حرفين لفظها ردف\nوالنون في الآخر كالهمز وفي ... نحو غضنفر أصالة كفي\nوالتاء في التأنيث والمضارعه ... ونحو الاستفعال والمطاوعه\nوالهاء وقفا كلمه ولم نره ... واللام في الإشارة المشتهره\nوامنع زيادة بلا قيد ثبت ... إن لم تبين حجة كحظلت"},{"id":"alfiyya:74","bookId":"alfiyya","type":"section","seq":74,"chapter":"مقدمة المؤلف","title":"فصل في زيادة همزة الوصل","page":"ج1 ص75","text":"للوصل همز سابق لا يثبت ... إلا إذا ابتدى به كاستثبتوا\nوهو لفعل ماض احتوى على ... أكثر من أربعة نحو انجلى\nوالأمر والمصدر منه وكذا ... أمر الثلاثي كاخش وامض وانفذا\nوفي اسم است ابن ابنم سمع ... واثنين وامرئ وتأنيث تبع\nوايمن همز أل كذا ويبدل ... مدا في الاستفهام أو يسهل"},{"id":"alfiyya:75","bookId":"alfiyya","type":"section","seq":75,"chapter":"مقدمة المؤلف","title":"الإبدال","page":"ج1 ص75","text":"أحرف الإبدال هدأت موطيا ... فأبدل الهمزة من واو ويا\nآخرا اثر ألف زيد وفى ... فاعل ما أعل عينا ذا اقتفي\nوالمد زيد ثالثا في الواحد ... همزا يرى في مثل كالقلائد\nكذاك ثاني لينين اكتنفا ... مد مفاعل كجمع نيفا\nوافتح ورد الهمز يا فيما أعل ... لاما وفي هراوة جعل\nواوا وهمزا أول الواوين رد ... في بدء غير شبه ووفي الأشد\nومدا ابدل ثاني الهمزين من ... كلمة ان يسكن كآثر وائتمن\nإن يفتح اثر ضم او فتح قلب ... واوا وياء إثر كسر ينقلب\nذو الكسر مطلقا كذا وما يضم ... واوا أصر ما لم يكن لفظا أتم\nفذاك ياء مطلقا جا وأؤم ... ونحوه وجهين في ثانيه أم\nوياء اقلب ألفا كسرا تلا ... أو ياء تصغير بواو ذا افعلا\nفي آخر أو قبل تا التأنيث أو ... زيادتي فعلان ذا أيضا رأوا\nفي مصدر المعتل عينا والفعل ... منه صحيح غالبا نحو الحول\nوجمع ذي عين أعل أو سكن ... فاحكم بذا الإعلال فيه حيث عن\nوصححوا فعلة وفي فعل ... وجهان والإعلال أولى كالخيل\nوالواو لاما بعد فتح يا انقلب ... لمعطيان يرضيان ووجب\nإبدال واو بعد ضم من ألف ... ويا كموقن بذا لها اعترف\nويكسر المضموم في جمع كما ... يقال هيم عند جمع أهيما\nوواوا اثر الضم رد اليا متى ... ألفي لام فعل او من قبل تا\nكتاء بان من رمى كمقدره ... كذا إذا كسبعان صيره\nوإن تكن عينا لفعلى وصفا ... فذاك بالوجهين عنهم يلفى"},{"id":"alfiyya:76","bookId":"alfiyya","type":"section","seq":76,"chapter":"مقدمة المؤلف","title":"فصل","page":"ج1 ص77","text":":\nمن لام فعلى اسما أتى الواو بدل ... ياء كتقوى غالبا جا ذا البدل\nبالعكس جاء لام فعلى وصفا ... وكون قصوى نادرا لا يخفى"},{"id":"alfiyya:77","bookId":"alfiyya","type":"section","seq":77,"chapter":"مقدمة المؤلف","title":"فصل","page":"ج1 ص77","text":":\nإن يسكن السابق من واو ويا ... واتصلا ومن عروض عزيا\nفياء الواو اقلبن مدغما ... وشذ معطى غير ما قد رسما\nمن واو أو ياء بتحريك أصل ... ألفا أبدل بعد فتح متصل\nإن حرك التالي وإن سكن كف ... إعلال غير اللام وهي لا يكف\nإعلالها بساكن غير ألف ... أو ياء التشديد فيها قد ألف\nوصح عين فعل وفعلا ... ذا أفعل كأغيد وأحولا\nوإن يبن تفاعل من افتعل ... والعين واو سلمت ولم تعل\nوإن لحرفين ذا الإعلال استحق ... صحح أول وعكس قد يحق\nوعين ما اخره قد زيد ما ... يخص الاسم واجب أن يسلما\nوقبل يا اقلب ميما النون إذا ... كان مسكنا كمن بت انبذا"},{"id":"alfiyya:78","bookId":"alfiyya","type":"section","seq":78,"chapter":"مقدمة المؤلف","title":"فصل","page":"ج1 ص78","text":":\nلساكن صح انقل التحريك من ... ذي لين آت عين فعل كابن\nما لم يكن فعل تعجب ولا ... كابيض أو أهوى بلام عللا\nومثل فعل في ذا الاعلال اسم ... ضاهي مضارعا وفيه وسم\nومفعل صحح كالمفعال ... وألف الإفعال واستفعال\nأزل لذا الإعلال والتا الزم عوض ... وحذفها بالنقل ربما عرض\nوما لإفعال من الحذف ومن ... نقل فمفعول به أيضا قمن\nنحو مبيع ومصون وندر ... تصحيح ذي الواو وفي ذي اليا اشتهر\nوصحح المفعول من نحو عدا ... وأعلل ان لم تتحر الأجودا\nكذاك ذا وجهين جا الفعول من ... ذي الواو لام جمع او فرد يعن\nوشاع نحو نيم في نوم ... ونحو نيام شذوذه نمي"},{"id":"alfiyya:79","bookId":"alfiyya","type":"section","seq":79,"chapter":"مقدمة المؤلف","title":"فصل","page":"ج1 ص78","text":":\nذو اللين فاتا في افتعال أبدلا\n... وشذ في ذي الهمز نحو ائتكلا\nطاتا افتعال رد إثر مطبق\n... في ادان وازدد وادكر دالا بقي"},{"id":"alfiyya:80","bookId":"alfiyya","type":"section","seq":80,"chapter":"مقدمة المؤلف","title":"فصل","page":"ج1 ص79","text":"فا أمر او مضارع من كوعد ... احذف وفي كعدة ذاك اطرد\nوحذف همز أفعل استمر في ... مضارع وبنيتي متصف\nظلت وظلت في ظللت استعملا ... وقرن في اقررن وقرن نقلا"},{"id":"alfiyya:81","bookId":"alfiyya","type":"section","seq":81,"chapter":"مقدمة المؤلف","title":"الإدغام","page":"ج1 ص79","text":"أول مثلين محركين في ... كلمة ادغم لا كمثل صفف\nوذلل وكلل ولبب ... ولا كجسس ولا كاخصص ابي\nولا كهيلل وشذ في ألل ... ونحوه فك بنقل فقبل\nوحيي افكك وادغم دون حذر ... كذاك نحو تتجلى واستتر\nوما بتاءين ابتدي قد يقتصر ... فيه على تاكبين العبر\nوفك حيث مدغم فيه سكن ... لكونه بمضمر الرفع اقترن\nنحو حللت ما حللته وفي ... جزم وشبه الجزم تخيير قفي\nوفك أفعل في التعجب التزم ... والتزم الإدغام أيضا في هلم"},{"id":"alfiyya:82","bookId":"alfiyya","type":"section","seq":82,"chapter":"مقدمة المؤلف","title":"الخاتمه","page":"ج1 ص80","text":"وما بجمعه عنيت قد كمل ... نظما على جل المهمات اشتمل\nأحصى من الكافية الخلاصة ... كما اقتضى غنى بلا خصاصه\nفأحمد الله مصليا على ... محمد خير نبي أرسلا\nوآله الغر الكرام البررة ... وصحبه المنتخبين الخيرة"}]};